const unsavedCases=new Set();
let creatorFilter='',members=loadMembers();
let caseSortKey='',caseSortDirection=1;
let casePageIndex=0;
const CASE_PAGE_SIZE=10;
let workSearch="",workStatus="全部",workSort="original";
let wizardDraft=null;
let pendingDeleteCaseIds=[];
let caseDeleteMode=false, selectedCaseIds=new Set();
let zoomLevel=100, drawingResizeObserver=null;
let demoUser={...members.find(m=>m.id==='member-1')};
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const seed=()=>[{id:'RFQ-260927-01',name:'精密固定座模具詢價',client:'客戶 A · 精密零件',owner:'陳怡安',due:'2026-09-29',rule:'A',files:[{name:'BRACKET-A01.pdf',status:'待確認',notes:[],accepted:false},{name:'HOUSING-A02.pdf',status:'待確認',notes:[],accepted:false},{name:'PLATE-A03.pdf',status:'處理失敗',notes:[],accepted:false}]},{id:'RFQ-260926-02',name:'外殼零件圖面整理',client:'客戶 B · 工業設備',owner:'林佳蓉',due:'2026-09-30',rule:'B',files:[{name:'COVER-B01.pdf',status:'可匯出',notes:[],accepted:true}]},{id:'RFQ-260925-03',name:'連接件模具前置作業',client:'客戶 C · 機械製造',owner:'陳怡安',due:'2026-09-28',rule:'manual',files:[{name:'LINK-C01.pdf',status:'已匯出',notes:[],accepted:true}]}];
let cases=seed(),cid=cases[0].id,fi=0,route='dashboard',filter='全部',query='',view='處理預覽',selectedNote=-1,logs=[{caseId:cases[2].id,file:'LINK-C01.pdf',version:'v1',time:'09/26 16:20',action:'模擬匯出'}],pendingNames=[];
const current=()=>wizardDraft||cases.find(c=>c.id===cid)||cases[0],file=()=>current().files[fi],all=()=>cases.flatMap(c=>c.files),badge=s=>`<span class="badge ${s==='處理失敗'?'red':s==='待確認'?'amber':s==='已匯出'||s==='可匯出'||s==='已確認'?'green':'blue'}">${s}</span>`;
function notify(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(window.tt);window.tt=setTimeout(()=>$('#toast').style.display='none',2600)}
function writeCaseStore(nextCases=cases,nextLogs=logs){try{localStorage.setItem('gam264-case-progress',JSON.stringify({version:1,cases:nextCases,logs:nextLogs,cid,fi}));unsavedCases.clear();return true}catch(e){notify('儲存失敗：瀏覽器儲存空間不足或無法使用，請勿關閉頁面。');return false}}
function loadCaseStore(){try{const data=JSON.parse(localStorage.getItem('gam264-case-progress')||'null');if(data?.version===1&&Array.isArray(data.cases)&&data.cases.every(c=>typeof c.id==='string'&&typeof c.name==='string'&&Array.isArray(c.files))){cases=data.cases;logs=Array.isArray(data.logs)?data.logs:[];cid=cases.some(c=>c.id===data.cid)?data.cid:cases[0]?.id;fi=Math.max(0,Math.min(data.fi||0,(current()?.files.length||1)-1));pendingNames=current()?.pendingNames||[]}}catch(e){notify('無法讀取已儲存進度，已載入示範資料。')}}
function saveCaseProgress(){const c=current();if(!c)return;const editor=document.querySelector('#noteText');if(route==='work'&&selection?.type==='note'&&editor){const n=selectedObject();if(n){n.text=editor.innerText;n.html=cleanNoteHtml(editor.innerHTML)}}if(route==='setup')c.rule=document.querySelector('#rule').value;c.pendingNames=[...pendingNames];c.resumeRoute=route;c.resumeFile=fi;const previous=c.savedAt;c.savedAt=new Date().toISOString();if(writeCaseStore()){notify('案件進度已儲存於此瀏覽器，可稍後繼續編輯。');render();return true}else{c.savedAt=previous;return false}}
function resumeCase(){const c=current();pendingNames=c.pendingNames||[];fi=Math.max(0,Math.min(c.resumeFile||0,c.files.length-1));go(['import','setup','work','review','export'].includes(c.resumeRoute)?c.resumeRoute:(c.files.length?'work':'import'))}
function deleteCase(){const c=current();if(c)openCaseDeleteDialog([c.id])}
function cancelCaseWizard(){wizardDraft=null;pendingNames=[];go('cases')}
function wizardSteps(active){return `<ol class="wizard-steps" aria-label="建立案件進度">${['案件資訊','匯入圖面','選擇規則'].map((label,i)=>`<li class="wizard-step ${i+1<active?'complete':i+1===active?'current':''}" ${i+1===active?'aria-current="step"':''}>${i+1<active?'<span class="step-check" aria-label="已完成">✓</span>':''}<span>步驟 ${i+1}</span><span>${label}</span></li>`).join('')}</ol>`}
function go(r){location.hash=r}function openCase(id){cid=id;fi=0;pendingNames=current().pendingNames||[];go('case')}function openFile(n){if(current().files[n]?.status==='處理失敗'){openFailureDialog(n);return;}zoomLevel=100;const viewport=document.querySelector('#drawingViewport');if(viewport){viewport.scrollLeft=0;viewport.scrollTop=0}fi=n;selectedNote=-1;view='處理預覽';go('work');if(route==='work')render()}
function title(t,p,actions=''){if(['new','edit-case','import','setup'].includes(route)){actions='';p+=' · 完成三個步驟後自動儲存'}if(['work','review','export'].includes(route)&&current()&&(route!=='work'||current().files.length>0)){actions=`<div class="save-progress-group" aria-live="polite">${savedTimeLabel(current())}${caseIconButton('save','儲存進度','saveCaseProgress()')}</div>`+actions;}return `<div class="top"><div><div class="page-title-row">${pageBackButton()}<h1>${t}</h1></div><p>${p}</p></div><div class="actions">${actions}</div></div>`}const btn=(t,act,cls='')=>`<button class="${cls}" onclick="${act}">${t}</button>`;
function toggleCaseDeleteMode(){caseDeleteMode=!caseDeleteMode;selectedCaseIds.clear();render()}
function selectCaseForDeletion(index,checked){const id=cases[index]?.id;if(!id)return;if(checked)selectedCaseIds.add(id);else selectedCaseIds.delete(id);render()}
function selectAllVisibleCases(checked){selectedCaseIds.clear();if(checked)visibleCaseRows().forEach(c=>selectedCaseIds.add(c.id));render()}
function deleteSelectedCases(){openCaseDeleteDialog(matchingCases(filter).filter(c=>selectedCaseIds.has(c.id)).map(c=>c.id))}
function openCaseDeleteDialog(ids){const targets=cases.filter(c=>ids.includes(c.id));if(!targets.length)return;pendingDeleteCaseIds=targets.map(c=>c.id);let dialog=document.querySelector('#caseDeleteDialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='caseDeleteDialog';dialog.setAttribute('aria-labelledby','caseDeleteTitle');document.body.appendChild(dialog)}dialog.innerHTML=`<h2 id="caseDeleteTitle">刪除 ${targets.length} 個案件？</h2><p>以下案件的圖面、備註與儲存進度將一併刪除，無法復原。</p><ul class="delete-case-list">${targets.map(c=>`<li><strong>${esc(c.name)}</strong><br><small>${esc(c.id)}</small></li>`).join('')}</ul><p id="caseDeleteError" role="alert"></p><div class="actions"><button autofocus onclick="closeCaseDeleteDialog()">取消</button><button class="confirm-case-delete" onclick="confirmCaseDeletion()">確認刪除</button></div>`;dialog.oncancel=()=>{pendingDeleteCaseIds=[]};dialog.showModal()}
function closeCaseDeleteDialog(){pendingDeleteCaseIds=[];document.querySelector('#caseDeleteDialog').close()}
function confirmCaseDeletion(){const ids=new Set(pendingDeleteCaseIds),count=cases.filter(c=>ids.has(c.id)).length;if(!count){closeCaseDeleteDialog();return}const next=cases.filter(c=>!ids.has(c.id)),nextLogs=logs.filter(l=>!ids.has(l.caseId));if(!writeCaseStore(next,nextLogs)){document.querySelector('#caseDeleteError').textContent='刪除未完成：無法更新瀏覽器儲存資料，請重試。';return}cases=next;logs=nextLogs;if(ids.has(cid)){cid=cases[0]?.id;fi=0;pendingNames=[];selection=null}selectedCaseIds.clear();caseDeleteMode=false;closeCaseDeleteDialog();go('cases');render();notify('已刪除 '+count+' 個案件')}

function caseDeleteToolbar(){return caseDeleteMode?`<div class="batch-actions"><span role="status">已選取 ${selectedCaseIds.size} 個案件</span><button onclick="toggleCaseDeleteMode()">取消</button><button class="danger-text" ${selectedCaseIds.size?'':'disabled'} onclick="deleteSelectedCases()">刪除選取案件</button></div>`:`<button class="case-delete-toggle" aria-label="選取案件以刪除" title="刪除案件" ${cases.length?'':'disabled'} onclick="toggleCaseDeleteMode()"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/></svg></button>`}
function matchingCases(status){return cases.filter(c=>(status==='全部'||c.files.some(f=>f.status===status))&&(!creatorFilter||c.owner===creatorFilter)&&(!query||(c.name+c.client).toLowerCase().includes(query.toLowerCase())))}
function caseFilterOptions(){return ['全部','待確認','處理失敗','可匯出','已匯出'].map(s=>`<option value="${s}" ${filter===s?'selected':''}>${s}(${matchingCases(s).length})</option>`).join('')}
function updateCaseSearch(value){query=value;casePageIndex=0;selectedCaseIds.clear();document.querySelector('tbody').innerHTML=caseRows();document.querySelector('#caseStatusFilter').innerHTML=caseFilterOptions();document.querySelector('#caseDeleteControls').innerHTML=caseDeleteToolbar();document.querySelector('#casePagination').innerHTML=casePaginationContent();const allBox=document.querySelector('#selectAllCases');if(allBox)allBox.checked=false}
function openCaseRow(event,index){if(route==='cases'&&caseDeleteMode)return;if(event.target.closest('button,a,input,select,textarea,label'))return;if(event.type==='keydown'){if(event.target!==event.currentTarget||!['Enter',' '].includes(event.key))return;event.preventDefault()}const c=cases[index];if(c)openCase(c.id)}
function caseRows(){const rows=visibleCaseRows();return rows.length?rows.map(c=>`<tr class="case-row" ${route==='cases'&&caseDeleteMode?'':`tabindex="0" aria-label="開啟案件 ${esc(c.name)}" onclick="openCaseRow(event,${cases.indexOf(c)})" onkeydown="openCaseRow(event,${cases.indexOf(c)})"`}>${route==='cases'&&caseDeleteMode?`<td class="case-select"><input type="checkbox" aria-label="選取 ${esc(c.name)}" ${selectedCaseIds.has(c.id)?'checked':''} onchange="selectCaseForDeletion(${cases.indexOf(c)},this.checked)"></td>`:''}<td><b>${esc(c.name)}</b></td><td>${esc(c.client)}</td><td>${esc(c.owner||'未指定')}</td><td>${c.files.length} 份</td><td>${badge(!c.files.length?'未匯入':c.files.some(f=>f.status==='處理失敗')?'處理失敗':c.files.some(f=>f.status==='待確認')?'待確認':c.files.every(f=>f.status==='已匯出')?'已匯出':'可匯出')}</td><td>${c.due}</td><td>${btn('開啟案件 →',`openCase('${c.id}')`,'textbtn')}</td></tr>`).join(''):`<tr><td colspan="${route==='cases'&&caseDeleteMode?8:7}" class="empty">沒有符合條件的案件</td></tr>`}
function table(){return `<div class="tablewrap"><table><thead><tr>${route==='cases'&&caseDeleteMode?`<th class="case-select"><input id="selectAllCases" type="checkbox" aria-label="全選本頁案件" ${visibleCaseRows().length&&visibleCaseRows().every(c=>selectedCaseIds.has(c.id))?'checked':''} onchange="selectAllVisibleCases(this.checked)"></th>`:''}${caseSortHeading('name','案件名稱')}${caseSortHeading('client','客戶')}${caseSortHeading('owner','建立者')}${caseSortHeading('files','圖面')}<th>狀態</th>${caseSortHeading('due','交付日期')}<th></th></tr></thead><tbody>${caseRows()}</tbody></table></div>`}
let dashboardWeekKey='';
function dashboardWeeks(now=new Date()){
 const date=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(now),part=k=>Number(date.find(x=>x.type===k).value);
 const today=new Date(Date.UTC(part('year'),part('month')-1,part('day'))),cutoff=new Date(today);cutoff.setUTCDate(cutoff.getUTCDate()-29);
 const sunday=new Date(today);sunday.setUTCDate(sunday.getUTCDate()-sunday.getUTCDay());
 const fmt=d=>d.toISOString().slice(0,10).replaceAll('-','/'),weeks=[];
 for(let i=0;i<5;i++){const start=new Date(sunday);start.setUTCDate(start.getUTCDate()-7*i);const end=new Date(start);end.setUTCDate(end.getUTCDate()+6);if(end<cutoff)break;const from=start<cutoff?cutoff:start,to=end>today?today:end;weeks.push({key:fmt(start),start:from,end:to,label:fmt(from)+' – '+fmt(to)+(i===0?'（本週）':''),values:Array.from({length:7},(_,day)=>{const d=new Date(start);d.setUTCDate(d.getUTCDate()+day);return d<from||d>to?null:6+(Math.floor(d.getTime()/86400000)*7%19)})})}return weeks;
}
function metricInfo(status){const explanations={'待確認':'尚未完成最終核對的圖面總數，包含待人工確認及已確認但待最終核對的圖面。','處理失敗':'目前處理失敗、需要查看原因並重試的圖面總數。','可匯出':'已通過最終確認、尚未匯出的圖面總數。','已匯出':'已完成匯出的圖面總數。'};return `<span class="metric-info"><button type="button" aria-label="數據說明" aria-describedby="metric-help-${status}" onclick="event.stopPropagation();this.parentElement.classList.toggle('show-help')" onkeydown="event.stopPropagation();if(event.key==='Escape')this.parentElement.classList.remove('show-help')"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 11v6"/><circle cx="12" cy="7.5" r=".8" fill="currentColor" stroke="none"/></svg></button><span class="metric-tooltip" id="metric-help-${status}" role="tooltip">${explanations[status]}統計範圍為所有案件，單位為圖面份數；不受下方週區間影響。</span></span>`}
function weeklyChart(){const weeks=dashboardWeeks(),week=weeks.find(w=>w.key===dashboardWeekKey)||weeks[0],max=Math.max(1,...week.values.filter(v=>v!==null));return `<div class="cardhead weekly-heading"><div><h2>每週圖面處理量</h2><p class="chart-scope">${week.label}</p></div><select aria-label="選擇近一個月的週區間" onchange="dashboardWeekKey=this.value;render()">${weeks.map(w=>`<option value="${w.key}" ${week.key===w.key?'selected':''}>${w.label}</option>`).join('')}</select></div><div class="bars">${week.values.map((n,i)=>`<div class="barcol"><span>${n===null?'—':n}</span><div class="bar" style="height:${n===null?0:Math.round(n/max*88)}%"></div><span>${['日','一','二','三','四','五','六'][i]}</span></div>`).join('')}</div><p class="weekly-note">單位：份 · 近 30 天，週日至週六；本週截至今日。圖表為示範資料。</p>`}
let recentCaseStatus='全部';
function setRecentCaseStatus(status){recentCaseStatus=status;render();}
function openAllRecentCases(){filter=recentCaseStatus;query='';creatorFilter='';casePageIndex=0;go('cases');}
function recentCaseTabs(){return `<div class="recent-case-tabs" role="group" aria-label="最近案件狀態">${['全部','待確認','處理失敗','可匯出','已匯出'].map(s=>`<button type="button" aria-pressed="${recentCaseStatus===s}" class="${recentCaseStatus===s?'active':''}" onclick="setRecentCaseStatus('${s}')">${s} (${matchingCases(s).length})</button>`).join('')}</div>`;}
function dashboard(){filter=recentCaseStatus;query='';creatorFilter='';casePageIndex=0;const stats=[['待人工確認',all().filter(f=>f.status==='待確認').length,'待確認','amber'],['需處理的異常',all().filter(f=>f.status==='處理失敗').length,'處理失敗','red'],['可匯出圖面',all().filter(f=>f.status==='可匯出').length,'可匯出','green'],['已匯出圖面',all().filter(f=>f.status==='已匯出').length,'已匯出','green']];return title('工作總覽','掌握圖面進度，從今天的待辦開始。',btn('＋ 建立案件',"go('new')",'primary'))+`<div class="metrics">${stats.map(([t,n,s,col])=>`<div class="card metric" role="button" tabindex="0" onclick="filter='${s}';go('cases')" onkeydown="if(event.key==='Enter'){filter='${s}';go('cases')}"><div class="metric-heading"><span>${t}</span>${metricInfo(s)}</div><strong>${String(n).padStart(2,'0')}</strong><small>點選查看相關案件 →</small></div>`).join('')}</div><div class="grid"><section class="card">${weeklyChart()}</section><section class="card"><div class="cardhead"><div><h2>所有案件圖面狀態分布</h2><p class="chart-scope">目前 ${cases.length} 件示範案件，含所有圖面</p></div><span class="pill">${all().length} 份圖面</span></div><div class="donutrow"><div class="donut" style="background:conic-gradient(var(--chart-confirmed) 0 ${all().filter(f=>['可匯出','已匯出'].includes(f.status)).length/(all().length||1)*100}%,var(--chart-pending) 0 ${(all().length-all().filter(f=>f.status==='處理失敗').length)/(all().length||1)*100}%,var(--chart-failed) 0)"><div><b>${all().length}</b><small>總圖面數</small></div></div><div class="legend"><div><i class="chart-confirmed"></i>已確認 ${all().filter(f=>['可匯出','已匯出'].includes(f.status)).length}</div><div><i class="chart-pending"></i>待確認 ${all().filter(f=>f.status==='待確認').length}</div><div><i class="chart-failed"></i>處理失敗 ${all().filter(f=>f.status==='處理失敗').length}</div></div></div></section></div><section class="card"><div class="cardhead"><h2>最近案件</h2>${btn('全部案件',"openAllRecentCases()",'textbtn')}</div>${recentCaseTabs()}${table()}</section>`}
function casesPage(){return title('案件管理','案件、圖面與處理狀態集中管理。',btn('＋ 建立案件',"go('new')",'primary'))+`<section class="card"><div class="toolbar case-list-toolbar"><input class="case-search-input" type="search" aria-label="搜尋案件" placeholder="搜尋案件名稱或客戶" value="${esc(query)}" oninput="updateCaseSearch(this.value)"><select id="caseStatusFilter" aria-label="篩選狀態及案件數量" onchange="filter=this.value;casePageIndex=0;selectedCaseIds.clear();render()">${caseFilterOptions()}</select><select aria-label="篩選建立者" onchange="creatorFilter=this.value;casePageIndex=0;selectedCaseIds.clear();render()"><option value="">全部建立者</option>${[...new Set(cases.map(c=>c.owner).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'zh-TW')).map(n=>`<option value="${esc(n)}" ${creatorFilter===n?'selected':''}>${esc(n)}</option>`).join('')}</select><div id="caseDeleteControls">${caseDeleteToolbar()}</div></div>${table()}<div id="casePagination" class="case-pagination">${casePaginationContent()}</div></section>`}
function defaultDueDate(now=new Date()){const parts=new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(now);return ['year','month','day'].map(k=>parts.find(p=>p.type===k).value).join('-')}
function defaultCaseName(now=new Date()){const parts=new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(now);const date=['year','month','day'].map(k=>parts.find(p=>p.type===k).value).join('');const prefix='案件_'+date+'-';const numbers=cases.map(c=>c.name.startsWith(prefix)?c.name.slice(prefix.length):'').filter(n=>/^\d+$/.test(n)).map(Number);return prefix+String(Math.max(0,...numbers)+1).padStart(2,'0')}
function syncCaseNameClear(){const input=document.querySelector('#caseName');document.querySelector('#clearCaseName').hidden=!input.value}
function clearCaseName(){const input=document.querySelector('#caseName');input.value='';syncCaseNameClear();input.focus()}
function newPage(){const editing=route==='edit-case',c=wizardDraft||(editing?current():null);return title(editing?'編輯案件資訊':'建立案件','建立基本資料，再匯入圖面進行處理。','')+`${wizardSteps(1)}<form class="card" onsubmit="createCase(event)"><div class="formgrid"><div class="field"><label for="caseName">案件名稱</label><div class="clearable-input"><input id="caseName" name="name" required value="${esc(c?.name??defaultCaseName())}" placeholder="請輸入案件名稱" oninput="syncCaseNameClear()"><button id="clearCaseName" type="button" aria-label="清除案件名稱" title="清除案件名稱" onclick="clearCaseName()"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18"/></svg></button></div></div><label class="field">客戶<select name="client">${['客戶 A · 精密零件','客戶 B · 工業設備','新客戶 · 人工確認',...(c&&!['客戶 A · 精密零件','客戶 B · 工業設備','新客戶 · 人工確認'].includes(c.client)?[c.client]:[])].map(client=>`<option ${c?.client===client?'selected':''}>${esc(client)}</option>`).join('')}</select></label><label class="field">建立者<input name="owner" value="${esc(c?.owner??demoUser.name)}" readonly required></label><label class="field">預定交付日<input name="due" type="date" value="${esc(c?.due??defaultDueDate())}" required></label></div><button class="primary" type="submit">下一步：匯入圖面</button></form>`}
function createCase(e){e.preventDefault();const d=new FormData(e.target),name=d.get('name').trim();if(!name)return;if(!wizardDraft){wizardDraft=route==='edit-case'?JSON.parse(JSON.stringify(current())):{id:'RFQ-'+Date.now().toString(36).toUpperCase()+'-'+Math.random().toString(36).slice(2,6).toUpperCase(),files:[],rule:'manual'};if(route!=='edit-case')pendingNames=[]}Object.assign(wizardDraft,{name,client:d.get('client'),owner:d.get('owner'),due:d.get('due')});go('import')}

function importPage(){return title('匯入圖面',esc(current().name),'')+`${wizardSteps(2)}<section class="card"><div class="upload"><div style="font-size:34px;color:#548a70">⇧</div><h2>加入這個案件的圖面</h2><p>原型只讀取檔名，不上傳或解析檔案內容。</p><div class="actions" style="justify-content:center;margin-top:15px">${btn('使用 3 份示範圖面',"pendingNames=['BRACKET-DEMO.pdf','HOUSING-DEMO.pdf','PLATE-DEMO.pdf'];render()",'primary')}<label style="border:1px solid #ddd;padding:8px 14px;border-radius:7px;cursor:pointer">選擇 PDF<input type="file" accept="application/pdf,.pdf" multiple hidden onchange="pickFiles(this.files)"></label></div></div>${pendingNames.length?pendingNames.map(n=>`<div class="checkrow">▱ ${esc(n)} <span class="pill">將使用示範圖預覽</span></div>`).join(''):'<p>尚未選擇檔案</p>'}<div class="footerbar">${btn('上一步：案件資訊',"go(wizardDraft && cases.some(c=>c.id===wizardDraft.id) ? 'edit-case' : 'new')")}<button class="primary" ${pendingNames.length?'':'disabled'} onclick="go('setup')">下一步：選擇規則 →</button></div></section>`}
function pickFiles(fs){pendingNames=[...fs].filter(f=>/\.pdf$/i.test(f.name)).map(f=>f.name);render();if(pendingNames.length!==fs.length)notify('僅接受 PDF 檔名，其他檔案已略過')}
function setupPage(){return title('選擇客戶規則','確認適用的規則；陌生版型可先人工處理。')+`${wizardSteps(3)}<section class="card"><label class="field">套用規則<select id="rule" onchange="current().rule=this.value"><option value="A" ${current().rule==='A'?'selected':''}>客戶 A · 右下圖框 v1.2</option><option value="B" ${current().rule==='B'?'selected':''}>客戶 B · 左上標誌 v1.0</option><option value="manual" ${current().rule==='manual'?'selected':''}>不套用規則 · 人工圈選</option></select></label><div class="note">規則只提供候選位置，仍需人工逐檔確認。原始圖面保留不變。</div><div class="footerbar">${btn('上一步：匯入圖面',"go('import')")}${btn('完成並建立處理任務','startJobs()','primary')}</div></section>`}
function startJobs(){if(!pendingNames.length){notify('請先匯入圖面。');go('import');return}const c=JSON.parse(JSON.stringify(current()));c.rule=$('#rule').value;c.files.push(...pendingNames.map((name,i)=>({name,status:i===2?'處理失敗':'待確認',notes:[],accepted:false})));c.pendingNames=[];c.resumeRoute='case';c.savedAt=new Date().toISOString();const next=cases.some(x=>x.id===c.id)?cases.map(x=>x.id===c.id?c:x):[c,...cases];const oldId=cid;cid=c.id;if(!writeCaseStore(next,logs)){cid=oldId;return}cases=next;wizardDraft=null;pendingNames=[];fi=0;go('case');notify('案件與處理任務已建立，進度已自動儲存。')}

function casePage(){let c=current();const rules=[...new Set(c.files.map(f=>f.rule||c.rule||'manual'))];return `<div class="case-heading"><div class="case-title">${pageBackButton()}<h1>${esc(c.name)}</h1>${caseIconButton('edit','修改案件名稱','openRenameCase()')}</div><div class="case-identity"><span>${esc(c.client)}</span></div><div class="case-actions"><div class="case-utilities">${savedTimeLabel(c)}${caseIconButton('save','儲存進度','saveCaseProgress()')}${caseIconButton('trash','刪除案件','deleteCase()')}</div><div class="actions">${btn('＋ 匯入圖面','openCaseImport()',c.files.length?'':'primary')}${caseExportButton(c)}</div></div></div><div class="case-deadline"><svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 11h18"/></svg><label for="caseDueDate">預定交付日</label><input id="caseDueDate" type="date" required value="${esc(c.due)}" aria-label="修改預定交付日" title="修改預定交付日" onchange="updateCaseDueDate(this)"></div><section class="card"><div class="cardhead case-list-heading"><div><h2>圖面處理清單</h2><span class="case-total">總計 ${c.files.length} 份圖面</span></div><span class="pill">規則：${rules.length>1?'依各圖面套用':ruleLabel(rules[0]||c.rule)}</span></div>${c.files.length?`<div class="tablewrap"><table><thead><tr><th>檔案 / 版本</th><th>狀態</th><th>處理說明</th><th>操作</th></tr></thead><tbody>${c.files.map((f,i)=>`<tr><td><b>${esc(f.name)}</b><small>原檔保留 · 工作版本 v1 · ${ruleLabel(f.rule||c.rule)}</small></td><td>${badge(f.status)}</td><td>${f.status==='處理失敗'?'示範錯誤：文字辨識失敗':'敏感區與圖面備註待核對'}</td><td>${f.status==='處理失敗'?btn('重試',`retry(${i})`):btn('開啟工作台 →',`openFile(${i})`,'textbtn')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">尚無圖面，點選上方「匯入圖面」開始處理。</div>'}</section><section class="card" style="margin-top:20px"><h2>案件紀錄</h2><div class="timeline"><p>建立者：${esc(c.owner)} · 案件已建立</p><p>原型中的檔案處理、檢核及匯出皆為示範</p>${logs.filter(l=>l.caseId===c.id).map(l=>`<p>${esc(l.time)} · ${esc(l.file)} · ${esc(l.action)}</p>`).join('')}</div></section>`}
function retry(i){const f=current().files[i];if(!f)return;f.status='待確認';markCaseUnsaved();logs.push({caseId:cid,file:f.name,time:new Date().toLocaleTimeString('zh-TW'),action:'重試成功（模擬）'});render();notify('重試成功（模擬），請點選該檔案開始確認')}
function drawing(){return `<svg viewBox="0 0 700 560" aria-label="虛構固定座工程示意圖"><defs><pattern id="grid" width="20" height="20" patternUnits="userSpaceOnUse"><path d="M20 0H0V20" fill="none" stroke="#eff2ef" stroke-width=".4"/></pattern></defs><rect x="18" y="18" width="664" height="524" fill="url(#grid)" stroke="#86968d"/><g fill="none" stroke="#627c72" stroke-width="2"><path d="M125 140H405V310H125Z M145 160H385V290H145Z"/><circle cx="190" cy="195" r="21"/><circle cx="340" cy="195" r="21"/><circle cx="190" cy="255" r="21"/><circle cx="340" cy="255" r="21"/><path d="M125 365H405V405H125Z M145 365V405 M385 365V405 M470 140H510V310H470Z"/><path d="M110 120H420 M125 100V132 M405 100V132 M90 140V310 M78 140H110 M78 310H110" stroke-width="1"/><path d="M265 125V325 M110 225H420" stroke-dasharray="8 4" stroke-width="1"/></g><g fill="#627c72" font-family="monospace" font-size="12"><text x="252" y="112">120.00</text><text x="47" y="225">80.00</text><text x="480" y="345">SECTION A-A</text><text x="125" y="438">MATERIAL: DEMO-STEEL</text><text x="125" y="457">TOLERANCE: ±0.05 mm</text><text x="125" y="477">REMOVE SHARP EDGES</text></g><rect x="435" y="455" width="247" height="87" fill="white" stroke="#86968d"/><path d="M435 485H682 M435 512H682 M540 485V542" stroke="#86968d"/><g fill="#536d61" font-family="sans-serif" font-size="12"><text x="448" y="476">DEMO INDUSTRIES / 客戶標誌</text><text x="448" y="504">BRACKET</text><text x="550" y="504">A-001 / REV.A</text><text x="448" y="531">DRAWN: DEMO</text><text x="550" y="531">SCALE 1:1</text><text x="37" y="47" font-size="10">SYNTHETIC DRAWING · 示範圖面，非生產用途</text></g></svg>`}
const panelState={properties:true,mask:true,note:false};
function panelToggle(key,el){panelState[key]=el.open}
function expandSelection(type){panelState.properties=true;panelState[type]=true}
let selection=null,recentColors=[],lastColors={mask:'#263B34',note:'#FFF1AE'};
try{const c=JSON.parse(localStorage.getItem('gam264-colors')||'{}');recentColors=(c.recent||[]).filter(validColor).slice(0,8);for(const t of ['mask','note'])if(validColor(c[t]))lastColors[t]=c[t]}catch(e){}
function validColor(c){return typeof c==='string'&&/^#[0-9a-f]{6}$/i.test(c)}
const initialMask=()=>({x:62,y:81,w:34,h:6,color:'#263B34',label:'客戶標誌與名稱'});
function ensureEditor(){let f=file();if(!f.masks)f.masks=[initialMask(),...(f.extraMasks||[]).map(m=>({...m,w:22,h:8,color:'#263B34',label:'手動遮蔽區'}))];f.notes.forEach(n=>{n.w??=28;n.h??=15;n.color??='#FFF1AE'});f.history??=[];if(selection?.file!==f.name)selection=null;return f}
function objects(type){let f=ensureEditor();return type==='mask'?f.masks:f.notes}function selectedObject(){return selection?objects(selection.type)[selection.index]:null}
function snapshot(){let f=ensureEditor();f.history.push(JSON.stringify({masks:f.masks,notes:f.notes,accepted:f.accepted}));if(f.history.length>25)f.history.shift();dirty()}
function undoEdit(){let f=ensureEditor();if(!f.history.length)return;let state=JSON.parse(f.history.pop());Object.assign(f,state);dirty();selection=null;render();notify('已復原上一步；請重新確認圖面')}
function pickObject(type,i,redraw=true){expandSelection(type);selection={file:file().name,type,index:i};if(redraw)render()}
function addMask(){ensureEditor();snapshot();file().masks.push({x:20,y:15,w:22,h:8,color:lastColors.mask,label:'手動遮蔽區'});file().accepted=false;view='處理預覽';pickObject('mask',file().masks.length-1)}
function addNote(){ensureEditor();snapshot();file().notes.push({text:'請填寫備註',x:18,y:55,w:28,h:15,color:lastColors.note});view='處理預覽';pickObject('note',file().notes.length-1)}
function acceptMask(){if(file().status==='處理失敗')return;file().accepted=true;markCaseUnsaved();render();notify('本張圖面已確認，可繼續確認其他圖面')}
function rejectMask(){snapshot();file().accepted=false;render()}
function cleanNoteHtml(html){const doc=new DOMParser().parseFromString(html,'text/html');const walk=node=>{if(node.nodeType===3)return esc(node.textContent);if(node.nodeType!==1)return '';const tag=node.tagName.toLowerCase();if(['script','style','iframe','object'].includes(tag))return '';const content=Array.from(node.childNodes).map(walk).join('');if(tag==='br')return '<br>';if(tag==='u')return '<u>'+content+'</u>';if(tag==='b'||tag==='strong')return '<strong>'+content+'</strong>';if(['ol','ul','li','p','div'].includes(tag))return '<'+tag+'>'+content+'</'+tag+'>';return content};return Array.from(doc.body.childNodes).map(walk).join('')}
function noteMarkup(n){return n.html?cleanNoteHtml(n.html):esc(n.text).replace(/\n/g,'<br>')}
function formatNote(command){const editor=$('#noteText');editor.focus();document.execCommand(command,false,null);updateNoteFormat()}
function updateNoteFormat(){for(const [id,command] of [['noteBold','bold'],['noteUnderline','underline'],['noteNumbered','insertOrderedList']]){const button=document.querySelector('#'+id);if(button)button.setAttribute('aria-pressed',String(document.queryCommandState(command)))}}
function pasteNote(event){event.preventDefault();document.execCommand('insertText',false,event.clipboardData.getData('text/plain'))}
function fitNote(el){const i=+el.dataset.index,n=file().notes[i],paper=document.querySelector('#paper');if(!n||!paper)return;const ph=paper.getBoundingClientRect().height;if(!ph)return;const content=el.querySelector('.object-content');content.style.height='auto';const need=Math.max(n.h,Math.ceil((content.scrollHeight+4)/ph*100));n.h=Math.min(100,need);n.y=Math.max(0,Math.min(n.y,100-n.h));el.style.height=n.h+'%';el.style.top=n.y+'%';content.style.height='100%';content.style.overflowY=need>100?'auto':'hidden'}
function fitAllNotes(){document.querySelectorAll('.noteobject').forEach(fitNote)}
function beginInlineNote(el){const content=el.querySelector('.object-content');if(content.isContentEditable)return;snapshot();content.contentEditable='true';content.setAttribute('role','textbox');content.setAttribute('aria-label','直接編輯備註文字');el.classList.add('inline-editing');content.oninput=()=>{const n=file().notes[+el.dataset.index];n.html=cleanNoteHtml(content.innerHTML);n.text=content.innerText;fitNote(el)};content.onpaste=pasteNote;content.onkeydown=e=>{e.stopPropagation();if(e.key==='Escape'||((e.ctrlKey||e.metaKey)&&e.key==='Enter')){e.preventDefault();content.blur()}};content.onblur=()=>{content.oninput();content.contentEditable='false';el.classList.remove('inline-editing');render()};content.focus();const range=document.createRange();range.selectNodeContents(content);range.collapse(false);const sel=window.getSelection();sel.removeAllRanges();sel.addRange(range)}
function saveNote(){let n=selectedObject();if(!n||selection.type!=='note')return;const editor=$('#noteText'),html=cleanNoteHtml(editor.innerHTML);snapshot();n.text=editor.innerText;n.html=html;render();notify('備註文字與格式已套用，請儲存案件進度')}

function deleteObject(type,i){snapshot();objects(type).splice(i,1);if(type==='mask')file().accepted=false;selection=null;render();notify('已刪除，可按復原恢復')}
function clearObjects(type,reset=false){let name=type==='mask'?'遮蔽區':'備註色塊';let detail=reset?(type==='mask'?'恢復初始 1 個候選遮蔽區，移除手動新增區域。':'恢復初始無備註狀態。'):'刪除本張圖面的全部'+name+'。';if(!confirm(detail+'\n不影響另一類物件，可按「復原」恢復。'))return;snapshot();file()[type==='mask'?'masks':'notes']=reset&&type==='mask'?[initialMask()]:[];if(type==='mask')file().accepted=false;selection=null;render();notify(reset?'已重設此類物件':'已清空此類物件')}
function changeColor(color){if(!validColor(color)||!selectedObject()||!(selection.type==='mask'?['#000000','#FFFFFF']:['#FFF1AE','#FFDAD6','#CDEEFF','#D8F0DB','#E8DDF5']).includes(color.toUpperCase()))return;snapshot();selectedObject().color=color.toUpperCase();lastColors[selection.type]=color.toUpperCase();recentColors=[color.toUpperCase(),...recentColors.filter(c=>c.toUpperCase()!==color.toUpperCase())].slice(0,8);try{localStorage.setItem('gam264-colors',JSON.stringify({...lastColors,recent:recentColors}))}catch(e){}render()}
function setGeometry(key,value){let o=selectedObject(),v=Number(value);if(!o||!Number.isFinite(v))return;snapshot();o[key]=v;o.w=Math.min(100,Math.max(3,o.w));o.h=Math.min(100,Math.max(3,o.h));o.x=Math.max(0,Math.min(100-o.w,o.x));o.y=Math.max(0,Math.min(100-o.h,o.y));if(selection.type==='mask')file().accepted=false;render()}
function textColor(c){let a=c.slice(1).match(/../g).map(x=>parseInt(x,16)/255).map(x=>x<=.04045?x/12.92:((x+.055)/1.055)**2.4);return a[0]*.2126+a[1]*.7152+a[2]*.0722>.179?'#18212A':'#FFFFFF'}
function objectMarkup(type,o,i){let active=selection?.type===type&&selection.index===i;return `<div class="editobject ${type==='mask'?'maskobject':'noteobject'} ${active?'is-selected':''}" tabindex="0" role="button" aria-pressed="${active}" aria-label="${type==='mask'?'遮蔽區':'備註'} ${i+1}，按 Enter 編輯" data-type="${type}" data-index="${i}" style="left:${o.x}%;top:${o.y}%;width:${o.w}%;height:${o.h}%;background:${o.color};color:${textColor(o.color)}" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();pickObject('${type}',${i})}"><span class="object-number" style="${o.y<6?'top:4px;transform:none':''}" aria-hidden="true">${type==='mask'?'遮蔽':'備註'} ${i+1}</span><span class="object-content" ${type==='note'?'title="選取後點擊文字直接編輯；拖曳編號可移動便利貼"':''}>${type==='note'?noteMarkup(o):''}</span>${active?`<button class="object-delete" aria-label="刪除此物件" onclick="event.stopPropagation();deleteObject('${type}',${i})">×</button>${['nw','ne','sw','se'].map(h=>`<span class="resize-handle ${h}" data-handle="${h}"></span>`).join('')}`:''}</div>`}
function editorPanel(){
let f=ensureEditor(),o=selectedObject(),type=selection?.type;
const name=t=>t==='mask'?'遮蔽區':'備註色塊';
const swatch=c=>`<button class="color-swatch" style="background:${c}" title="${c}" aria-label="使用色彩 ${c}" aria-pressed="${o?.color.toUpperCase()===c.toUpperCase()}" onclick="changeColor('${c}')"></button>`;
return `<div class="inspector-heading"><h3>圖面物件</h3><span class="pill">${f.masks.length+f.notes.length} 個</span></div>
<details class="editor-section" ${panelState.properties?'open':''} ontoggle="panelToggle('properties',this)"><summary><span>${o?name(type)+' '+(selection.index+1):'選取物件設定'}</span><span class="section-meta">${o?'已選取':'未選取'}</span></summary><div class="section-content">
${o?`<div class="selection-tools"><span>物件設定</span>${btn('刪除此物件',`deleteObject('${type}',${selection.index})`,'danger-text')}</div><h3>填色</h3><div class="color-row">${(type==='mask'?['#000000','#FFFFFF']:['#FFF1AE','#FFDAD6','#CDEEFF','#D8F0DB','#E8DDF5']).map(swatch).join('')}</div>${type==='note'?`<h3 id="noteTextLabel">備註內容</h3><div class="note-format-toolbar" role="group" aria-label="備註文字格式">${[['noteBold','bold','粗體','<path d="M7 4h6a4 4 0 0 1 0 8H7zm0 8h7a4 4 0 0 1 0 8H7z"/>'],['noteUnderline','underline','底線','<path d="M6 3v7a6 6 0 0 0 12 0V3M4 21h16"/>'],['noteNumbered','insertOrderedList','編號清單','<path d="M10 6h11M10 12h11M10 18h11M3 3h1v5M3 8h3M3 13c3-2 4 1 1 3l-1 2h3"/>']].map(([id,cmd,label,path])=>`<button id="${id}" type="button" aria-label="${label}" aria-pressed="false" title="${label}" onmousedown="event.preventDefault()" onclick="formatNote('${cmd}')"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round" aria-hidden="true">${path}</svg></button>`).join('')}</div><div id="noteText" class="note-rich-editor" contenteditable="true" role="textbox" aria-multiline="true" aria-labelledby="noteTextLabel" onkeyup="updateNoteFormat()" onmouseup="updateNoteFormat()" oninput="updateNoteFormat()" onpaste="pasteNote(event)">${noteMarkup(o)}</div><p class="note-format-help">選取文字可切換粗體或底線；編號清單按 Enter 新增下一項，空白項再按 Enter 結束。按「儲存文字」套用至圖面。</p>${btn('儲存文字','saveNote()','primary')}`:'<p>遮蔽採不透明填色；實際 PDF 去識別化仍為模擬。</p>'}`:'<p>點選圖面編號或物件清單，即可調整尺寸、位置與顏色。</p>'}</div></details>
${['mask','note'].map(t=>`<details class="editor-section" ${panelState[t]?'open':''} ontoggle="panelToggle('${t}',this)"><summary><span>${name(t)}列表</span><span class="section-count">${objects(t).length}</span></summary><div class="section-content"><div class="object-list">${objects(t).map((a,i)=>`<div class="object-item"><button aria-pressed="${selection?.type===t&&selection?.index===i}" class="${selection?.type===t&&selection?.index===i?'active':''}" onclick="pickObject('${t}',${i})"><span class="list-swatch" style="background:${a.color}"></span><b>${name(t)} ${i+1}</b>${t==='note'?`<small>${esc(a.text.slice(0,24)||'空白備註')}</small>`:''}</button><button aria-label="刪除${name(t)} ${i+1}" onclick="deleteObject('${t}',${i})">×</button></div>`).join('')||`<p class="object-empty">尚無${name(t)}</p>`}</div><div class="group-actions"><button class="danger-text" ${objects(t).length?'':'disabled'} onclick="clearObjects('${t}')">全部刪除</button>${btn('重設',`clearObjects('${t}',true)`)}</div><small>${t==='mask'?'重設：恢復初始候選區':'重設：回到無備註狀態'}</small></div></details>`).join('')}
`}
function uiIcon(name){const paths={original:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><path d="M14 2v6h6M8 13h8M8 17h5"/>',preview:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/>',note:'<path d="M14 21H4V3h16v12zM14 21v-6h6M8 7h8M8 11h5"/>',mask:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="M7 9h10v6H7z" fill="currentColor" stroke="none"/>',undo:'<path d="M3 10h10a7 7 0 0 1 0 14" transform="translate(0 -4)"/><path d="M3 6l5-5M3 6l5 5"/>',clear:'<path d="M5 5l14 14M19 5L5 19"/>'};return `<svg class="ui-icon" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${paths[name]||''}</svg>`}
function clearSelection(){if(!selection)return;selection=null;render();document.querySelector('#paper')?.focus({preventScroll:true})}
function sizeDrawing(){const viewport=document.querySelector('#drawingViewport'),paper=document.querySelector('#paper');if(!viewport||!paper)return;const width=Math.min(viewport.clientWidth,viewport.clientHeight*1.25)*zoomLevel/100;paper.style.width=width+'px';paper.style.height=width/1.25+'px';viewport.classList.toggle('can-pan',zoomLevel>100);fitAllNotes()}
function setZoom(value){const next=Math.max(50,Math.min(200,value)),viewport=document.querySelector('#drawingViewport'),paper=document.querySelector('#paper');if(!viewport||!paper)return;const ratio=next/zoomLevel,left=(viewport.scrollLeft+viewport.clientWidth/2)*ratio-viewport.clientWidth/2,top=(viewport.scrollTop+viewport.clientHeight/2)*ratio-viewport.clientHeight/2;zoomLevel=next;sizeDrawing();document.querySelector('#zoomValue').textContent=next+'%';document.querySelector('#zoomOut').disabled=next===50;document.querySelector('#zoomIn').disabled=next===200;viewport.scrollLeft=Math.max(0,left);viewport.scrollTop=Math.max(0,top);}
function bindPan(){const viewport=document.querySelector('#drawingViewport');if(!viewport)return;viewport.onpointerdown=e=>{if(e.button!==0||e.target.closest('.editobject'))return;e.preventDefault();const sx=e.clientX,sy=e.clientY,left=viewport.scrollLeft,top=viewport.scrollTop;let moved=false;viewport.setPointerCapture(e.pointerId);viewport.onpointermove=ev=>{const dx=ev.clientX-sx,dy=ev.clientY-sy;if(Math.abs(dx)+Math.abs(dy)>4)moved=true;if(moved&&zoomLevel>100){viewport.classList.add('panning');viewport.scrollLeft=left-dx;viewport.scrollTop=top-dy}};const finish=ev=>{viewport.onpointermove=null;viewport.onpointerup=null;viewport.onpointercancel=null;viewport.classList.remove('panning');if(viewport.hasPointerCapture(e.pointerId))viewport.releasePointerCapture(e.pointerId);if(!moved&&ev.type!=='pointercancel')clearSelection()};viewport.onpointerup=finish;viewport.onpointercancel=finish};}

function workFileList(){const entries=current().files.map((f,i)=>({f,i})).filter(({f})=>(workStatus==='全部'||workFileStatus(f)===workStatus)&&f.name.toLocaleLowerCase().includes(workSearch.toLocaleLowerCase()));if(workSort!=='original')entries.sort((a,b)=>a.f.name.localeCompare(b.f.name,'zh-TW',{numeric:true})*(workSort==='desc'?-1:1));return `<p class="file-result-count" role="status">顯示 ${entries.length} / ${current().files.length} 份</p>`+(entries.map(({f:x,i})=>`<button class="${i===fi?'selected':''} ${x.status==='處理失敗'?'file-error':''}" onclick="selection=null;openFile(${i})" title="${esc(x.name)}" ${i===fi?'aria-current="true"':''}><span class="file-name">${uiIcon('original')}<span>${esc(x.name)}</span></span>${badge(workFileStatus(x))}${x.status==='處理失敗'?'<small>查看原因與重試</small>':''}</button>`).join('')||'<p class="empty">沒有符合條件的圖面</p>')}
function workListControls(){return `<h3>圖面清單</h3><label class="work-filter">搜尋檔名<input type="search" value="${esc(workSearch)}" placeholder="輸入檔名" oninput="workSearch=this.value;refreshWorkFiles()"></label><label class="work-filter">處理狀態<select onchange="workStatus=this.value;refreshWorkFiles()">${['全部','待確認','已確認','處理失敗','可匯出','已匯出'].map(st=>`<option ${workStatus===st?'selected':''}>${st}</option>`).join('')}</select></label><label class="work-filter">排序<select onchange="workSort=this.value;refreshWorkFiles()">${[['original','匯入順序'],['asc','檔名 A → Z'],['desc','檔名 Z → A']].map(([v,t])=>`<option value="${v}" ${workSort===v?'selected':''}>${t}</option>`).join('')}</select></label>`}
function refreshWorkFiles(){const el=document.querySelector('#workFileResults');if(el)el.innerHTML=workFileList()}
function openFailureDialog(i){const f=current().files[i];if(!f)return;caseDialog('failureDialog',`<h2 id="failureDialogTitle">圖面處理失敗</h2><p class="failure-filename">${esc(f.name)}</p><strong>文字辨識失敗（示範）</strong><p>可能原因：掃描解析度不足、文字模糊，或圖檔格式無法解析。實際原因待正式處理服務回報。</p><p>可先檢查圖面清晰度與格式，再重新處理。</p><div class="actions"><button onclick="this.closest('dialog').close()">關閉</button><button class="primary" onclick="retry(${i});this.closest('dialog').close()">${uiIcon('undo')}重試處理</button></div>`)}

function workPage(){if(!current().files.length)return title('圖面工作台','請先建立案件並匯入圖面。',btn('建立案件',"go('new')",'primary'));let f=ensureEditor();if(f.status==='處理失敗')return title('這份圖面需要重試',esc(f.name),btn('重試',`retry(${fi})`,'primary'))+'';return title('圖面工作台',`${current().id} / ${esc(f.name)}`,''+btn(uiIcon('preview')+'預覽與確認',"go('review')",'primary next-step-action'))+`${drawingConfirmation(f)}<div class="workspace"><div class="filelist">${workListControls()}<div id="workFileResults" class="work-file-results">${workFileList()}</div></div><div class="canvaswrap"><div class="canvasbar">${['原圖','處理預覽'].map(v=>btn(uiIcon(v==='原圖'?'original':'preview')+v,`view='${v}';selection=null;render()`,view===v?'primary':'')).join('')}${btn(uiIcon('note')+'備註色塊','addNote()')}${btn(uiIcon('mask')+'遮蔽區','addMask()')}<button ${f.history.length?'':'disabled'} onclick="undoEdit()">${uiIcon('undo')}復原</button><button ${selection?'':'disabled'} onclick="clearSelection()">${uiIcon('clear')}取消選取</button></div><div class="drawing-stage"><div class="drawing-viewport" id="drawingViewport"><div class="paper" id="paper" style="width:${zoomLevel}%" tabindex="-1" aria-label="圖面編輯區">${drawing()}${view==='原圖'?'':f.masks.map((o,i)=>objectMarkup('mask',o,i)).join('')+f.notes.map((o,i)=>objectMarkup('note',o,i)).join('')}</div></div><div class="zoom-toolbar" role="group" aria-label="圖面縮放"><button id="zoomOut" aria-label="縮小圖面" title="縮小" ${zoomLevel===50?'disabled':''} onclick="setZoom(zoomLevel-25)"><svg class="ui-icon" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="10" cy="10" r="6"/><path d="M15 15l6 6M7 10h6"/></svg></button><output id="zoomValue" aria-live="polite">${zoomLevel}%</output><button id="zoomIn" aria-label="放大圖面" title="放大" ${zoomLevel===200?'disabled':''} onclick="setZoom(zoomLevel+25)"><svg class="ui-icon" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="10" cy="10" r="6"/><path d="M15 15l6 6M7 10h6M10 7v6"/></svg></button><button onclick="setZoom(100)" title="重設為適合目前視窗的基準大小">100%</button></div></div><p class="pan-hint">100% 為適合視窗；放大後拖曳空白處平移圖面。</p><p style="margin-top:10px">${view==='原圖'?'原圖唯讀，切換處理預覽即可編輯。':'點選物件可拖曳；備註選取後再點文字可直接編輯；完成後請儲存案件進度。拖曳編號移動便利貼，Esc 結束文字編輯。'}</p><p>示範圖面，非生產用途。修改後需重新確認。</p></div><div class="inspector">${view==='原圖'?'<h3>原圖檢視</h3><p>原始圖面不受修改。</p>'+btn('切換處理預覽',"view='處理預覽';render()",'primary'):editorPanel()}</div></div>`}
function dirty(){markCaseUnsaved();file().accepted=false;if(['可匯出','已匯出'].includes(file().status))file().status='待確認'}
function bindDrag(){bindPan();document.querySelectorAll('.editobject').forEach(el=>{el.onpointerdown=e=>{if(e.button!==0||e.target.closest('button')||e.target.closest('[contenteditable="true"]'))return;if(el.dataset.type==='note'&&selection?.type==='note'&&selection.index===+el.dataset.index&&e.target.closest('.object-content')){e.preventDefault();beginInlineNote(el);return}e.preventDefault();const type=el.dataset.type,i=+el.dataset.index,h=e.target.dataset.handle;const o=objects(type)[i],p=$('#paper').getBoundingClientRect();const sx=e.clientX,sy=e.clientY,orig={...o};let moved=false;expandSelection(type);selection={file:file().name,type,index:i};el.setPointerCapture(e.pointerId);el.onpointermove=ev=>{let dx=(ev.clientX-sx)/p.width*100,dy=(ev.clientY-sy)/p.height*100;if(Math.abs(dx)+Math.abs(dy)<.2&&!moved)return;if(!moved){snapshot();moved=true}if(h){let left=orig.x,top=orig.y,right=orig.x+orig.w,bottom=orig.y+orig.h;if(h.includes('w'))left=Math.max(0,Math.min(right-3,orig.x+dx));else right=Math.min(100,Math.max(left+3,orig.x+orig.w+dx));if(h.includes('n'))top=Math.max(0,Math.min(bottom-3,orig.y+dy));else bottom=Math.min(100,Math.max(top+3,orig.y+orig.h+dy));Object.assign(o,{x:left,y:top,w:right-left,h:bottom-top})}else{Object.assign(o,{x:Math.max(0,Math.min(100-o.w,orig.x+dx)),y:Math.max(0,Math.min(100-o.h,orig.y+dy))})}if(type==='mask')file().accepted=false;for(const [key,css] of [['x','left'],['y','top'],['w','width'],['h','height']])el.style[css]=o[key]+'%'};const finish=()=>{el.onpointermove=null;el.onpointerup=null;el.onpointercancel=null;render()};el.onpointerup=finish;el.onpointercancel=finish}})}
function reviewPage(){if(!current().files.length){go('case');return ''}let f=ensureEditor();const approved=isExportReady(f);return title('預覽與人工確認',esc(f.name)+' · 工作版本 v1',reviewExportAction())+exportSummary(current())+reviewProgress()+`<section class="card"><div class="cardhead"><h2>確認內容</h2>${badge(f.status)}</div><div class="note">本頁展示人工確認流程。遮蔽與安全檢查尚未實際執行。</div><label class="checkrow"><input type="checkbox" id="check1" onchange="syncReviewApproval()" ${approved?'checked disabled':''}> 敏感資訊位置已逐一核對</label><label class="checkrow"><input type="checkbox" id="check2" onchange="syncReviewApproval()" ${approved?'checked disabled':''}> 尺寸、公差及必要技術資訊保持完整</label><label class="checkrow"><input type="checkbox" id="check3" onchange="syncReviewApproval()" ${approved?'checked disabled':''}> ${f.notes.length?'備註內容與位置已確認':'本圖不需備註，已確認'}</label><div class="actions review-approval-actions"><button id="reviewApprove" class="primary" disabled onclick="approve()">${approved?'已通過':'確認通過'}</button><span id="reviewApprovalHint" class="review-important" role="status">${approved?'本張已通過最終確認':!f.accepted?'請先在工作台確認本張圖面':'請完成上方三項核對'}</span></div></section>`}

function returnReview(){let r=$('#reason').value.trim();if(!r)return notify('請填寫需要修正的原因');file().status='待確認';logs.push({caseId:cid,file:file().name,time:new Date().toLocaleTimeString('zh-TW'),action:'退回修正：'+r});go('work');notify('已退回修正，原因記錄於案件歷程')}
function approve(){if(isExportReady(file()))return;if(file().status==='處理失敗')return notify('請先重新處理失敗圖面');if(!['#check1','#check2','#check3'].every(s=>$(s).checked))return notify('請完成三項人工確認');if(!file().accepted)return notify('請先返回工作台確認本張圖面的遮蔽與備註');file().status='可匯出';logs.push({caseId:cid,file:file().name,time:new Date().toLocaleTimeString('zh-TW'),action:'人工確認通過（模擬）'});writeCaseStore();render();notify('這份圖面已列入可匯出清單，可繼續核對其他圖面')}
function exportPage(){let c=current(),ready=exportReadyFiles(c);return title('成果與匯出',`${c.id} · 僅列出通過最終確認的圖面`,'')+exportSummary(c)+`<section class="card"><div class="cardhead"><h2>可匯出項目 <span class="pill">${ready.length} 份</span></h2><button id="exportSelected" class="primary" ${ready.length?'':'disabled'} onclick="doExport()">匯出選取項目</button></div>${ready.length?ready.map(f=>`<label class="checkrow"><input class="exportcheck" onchange="syncExportSelection()" type="checkbox" value="${c.files.indexOf(f)}" checked><b>${esc(f.name)}</b>　${badge(f.status)}　<span class="pill">v1</span></label>`).join(''):'<div class="empty">尚無已通過的圖面，請先完成工作台與人工確認。</div>'}<div class="note">${c.files.length-ready.length} 份尚未通過最終確認的圖面未列入交付；可在「預覽與人工確認」查看進度。本原型不產生正式 PDF。</div></section><section class="card" style="margin-top:22px"><h2>匯出紀錄</h2><div class="tablewrap"><table><thead><tr><th>檔案</th><th>時間</th><th>結果</th></tr></thead><tbody>${logs.filter(l=>l.caseId===cid&&l.action==='模擬匯出').map(l=>`<tr><td>${esc(l.file)}</td><td>${l.time}</td><td>${badge('已匯出')} <small>模擬</small></td></tr>`).join('')||'<tr><td colspan="3" class="empty">尚無匯出紀錄</td></tr>'}</tbody></table></div></section>`}
function doExport(){let chosen=[...document.querySelectorAll('.exportcheck:checked')];if(!chosen.length)return notify('請至少選取一份已確認圖面');chosen.forEach(el=>{let f=current().files[+el.value];if(!['可匯出','已匯出'].includes(f.status))return;f.status='已匯出';markCaseUnsaved();logs.push({caseId:cid,file:f.name,time:new Date().toLocaleTimeString('zh-TW'),action:'模擬匯出'})});render();notify('模擬匯出完成，已更新紀錄；未產生正式檔案')}
function ruleThumbnail(kind){
const manual=kind==='人工',left=kind==='B';
const desc=manual?'未知版型：圖框與敏感資訊位置需逐檔確認':left?'客戶 B：左上標誌與工程人員姓名為候選敏感區，尺寸與技術註記保留':'客戶 A：右下圖框內 Logo 與客戶名稱為候選敏感區，尺寸與技術註記保留';
return `<figure class="rule-preview"><svg viewBox="0 0 360 250" role="img" aria-label="${desc}"><title>${desc}</title><rect x="10" y="10" width="340" height="230" rx="3" fill="#fff" stroke="#9caec0"/><path d="M10 46H350" stroke="#dce4ed"/><text x="24" y="33" fill="#53677a" font-size="13">${manual?'未知圖面版型 · 逐檔確認':'版型 '+kind+' · 圖面配置示意'}</text>
${manual?`<rect x="35" y="68" width="290" height="110" rx="5" fill="#f4f7fa" stroke="#8e9eae" stroke-dasharray="6 5"/><text x="180" y="117" text-anchor="middle" fill="#53677a" font-size="28">?</text><text x="180" y="147" text-anchor="middle" fill="#53677a" font-size="14">圖框及敏感資訊位置待確認</text><text x="180" y="210" text-anchor="middle" fill="#53677a" font-size="14">不預設遮蔽範圍，由業助人工圈選</text>`:`<rect x="38" y="${left?112: 60}" width="204" height="${left?65:105}" rx="3" fill="#edf6ff" stroke="#005bac"/><path d="M80 ${left?126:85}H200V${left?162:142}H80Z" fill="none" stroke="#5c7895" stroke-width="1.5"/><circle cx="100" cy="${left?144:114}" r="8" fill="white" stroke="#5c7895"/><circle cx="180" cy="${left?144:114}" r="8" fill="white" stroke="#5c7895"/><text x="254" y="150" fill="#005bac" font-size="13">保留</text><text x="40" y="194" fill="#005bac" font-size="13">尺寸／公差／材料與技術註記</text><rect x="${left?24:174}" y="${left?57:204}" width="${left?300:164}" height="${left?43:26}" rx="3" fill="#fff2d8" stroke="#ad6b00" stroke-width="1.5" stroke-dasharray="5 3"/><text x="${left?35:184}" y="${left?83:222}" fill="#875200" font-size="13">${left?'Logo／工程人員姓名':'Logo／客戶名稱'}</text>`}</svg><figcaption>${manual?'人工圈選 · 無預設遮蔽位置':'候選敏感區與保留內容位置示意'}</figcaption>${manual?'':`<div class="rule-preview-legend"><span><i class="sensitive-key"></i>候選敏感區</span><span><i class="retain-key"></i>應保留資訊</span></div>`}<small>示範版型，非真實客戶圖面</small></figure>`;
}
function rulesPage(){return title('客戶處理規則','把各客戶的圖面處理習慣，整理成可確認的規則。',btn('＋ 新增規則',"rulePlanned('新增')",'primary'))+`<div class="note">規則管理尚在規劃中，新增、編輯、複製及刪除入口僅供介面預覽。下方可搜尋與篩選示範規則。</div><section class="card rules-toolbar"><label>搜尋規則<input type="search" placeholder="搜尋規則名稱或敏感資訊" aria-label="搜尋規則名稱或敏感資訊" oninput="filterRuleCards()" id="ruleSearch"></label><label>客戶<select id="ruleCustomer" onchange="filterRuleCards()"><option value="all">全部客戶</option><option value="A">客戶 A</option><option value="B">客戶 B</option><option value="人工">未指定客戶 · 人工處理</option></select></label><span id="ruleCount" role="status">共 3 筆規則</span></section><div class="rulegrid">${[['A','右下圖框','v1.2','右下角 Logo、客戶名稱'],['B','左上標誌','v1.0','左上角 Logo、工程人員姓名'],['人工','未知版型','草稿','由業助逐項圈選']].map(([a,b,v,d])=>`<section class="card rule-card" data-customer="${a}"><div class="rule-card-top"><span class="pill">${v}</span><span class="rule-planned">管理功能待開發</span></div><h3>${a==='人工'?'人工處理':'客戶 '+a} · ${b}</h3><div class="rule-card-actions"><button onclick="rulePlanned('編輯','${a}')">${caseActionIcon('edit')}編輯</button><button onclick="rulePlanned('複製','${a}')">${caseActionIcon('copy')}複製</button><button class="case-icon danger-text" onclick="rulePlanned('刪除','${a}')" title="刪除規則（待開發）" aria-label="刪除規則（待開發）">${caseActionIcon('delete')}</button></div>${ruleThumbnail(a)}<p>敏感資訊</p><ul><li>${d}</li></ul><p>應保留資訊</p><ul><li>尺寸與公差</li><li>必要材料及技術註記</li></ul><div class="note">正式規則變更須經人工確認並保留版本。</div></section>`).join('')}</div><div id="rulesEmpty" class="empty" hidden>沒有符合條件的規則，請調整客戶或搜尋文字。</div>`}
function caseActionIcon(type){return `<svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${type==='copy'?'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>':type==='edit'?'<path d="m16 3 5 5-12 12-6 1 1-6zM14 5l5 5"/>':'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/>'}</svg>`}
function filterRuleCards(){const query=$('#ruleSearch').value.trim().toLocaleLowerCase(),customer=$('#ruleCustomer').value;let count=0;document.querySelectorAll('.rule-card').forEach(card=>{card.hidden=!((customer==='all'||card.dataset.customer===customer)&&card.textContent.toLocaleLowerCase().includes(query));if(!card.hidden)count++});$('#ruleCount').textContent=`共 ${count} 筆規則`;$('#rulesEmpty').hidden=count>0}
function rulePlanned(action,key){const name=({A:'客戶 A · 右下圖框',B:'客戶 B · 左上標誌',人工:'人工處理 · 未知版型'})[key]||'';caseDialog('rulePlannedDialog',`<h2 id="rulePlannedDialogTitle">${action}規則 · 待開發</h2><p>${action==='複製'?'複製後將自動命名為：':action==='新增'?'此入口預留規則名稱、客戶與圖面處理條件的設定。':'目前僅展示操作入口，尚未'+action+'規則。'}</p>${name?`<div class="note">${esc(name)}${action==='複製'?'－副本':''}</div>`:''}${action==='複製'?'<p>若名稱重複，將依序加上「副本 2」、「副本 3」。本次不會建立新規則。</p>':''}<div class="actions"><button class="primary" onclick="this.closest('dialog').close()">知道了</button></div>`)}

function tbdPage(type){let review=type==='approval';return title(review?'估價審批':'SQ 資料整理','後續流程規劃', '<span class="badge amber">TBD · 尚未納入主流程</span>')+`<div class="tbd">此頁用於需求討論。欄位、角色及啟用條件尚待企業確認。</div><div class="grid" style="margin-top:22px"><section class="card"><h2>預計承接內容</h2>${(review?['來源：已整理的案件與圖面','操作：閱讀圖面、留下意見、通過或退回','輸出：審批結果與原因']:['來源：案件資訊與已確認圖號','欄位：SQ 單號、客戶、圖號清單、發圖日','輸出：人工確認後的資料摘要']).map(t=>`<div class="checkrow">${t}</div>`).join('')}</section><section class="card"><h2>需要釐清</h2>${(review?['誰是正式審批者？','審批發生在圖面匯出前或估價階段？','是否每個案件都需要第二人複核？']:['SQ 真正建立時點？','哪些欄位必填、由誰確認？','與既有 ERP 如何分工？']).map(t=>`<div class="checkrow">${t}</div>`).join('')}<p style="margin-top:15px">本輪不模擬自動估價或 ERP 同步。</p></section></div>`}
const themes={janman:{label:'預設 · 品牌藍',primary:'#005BAC',hover:'#004780',soft:'#EAF3FA',accent:'#24A5DE',bg:'#F4F7FA',ink:'#243344',muted:'#637387',line:'#DCE4ED',bar:'#A8D2E4'},forest:{label:'原型經典 · 深綠',primary:'#186458',hover:'#104C42',soft:'#E7F1EB',accent:'#70A68D',bg:'#F4F7F5',ink:'#20332F',muted:'#687B70',line:'#DFE7E3',bar:'#B6D3C5'},slate:{label:'通用企業 · 石墨',primary:'#40546C',hover:'#2D3D51',soft:'#EAF0F6',accent:'#7694B4',bg:'#F5F7F9',ink:'#263342',muted:'#667589',line:'#DDE4EB',bar:'#BDCDDD'}};
let themeKey='janman';try{const saved=localStorage.getItem('gam264-theme');if(themes[saved])themeKey=saved}catch(e){}
function applyTheme(key,persist=false){if(!themes[key])return;themeKey=key;const t=themes[key];for(const [k,v] of Object.entries(t))if(k!=='label')document.documentElement.style.setProperty('--theme-'+k,v);document.documentElement.style.setProperty('--green',t.primary);document.documentElement.style.setProperty('--ink',t.ink);document.documentElement.style.setProperty('--muted',t.muted);document.documentElement.style.setProperty('--bg',t.bg);document.documentElement.style.setProperty('--line',t.line);document.documentElement.dataset.theme=key;if(persist){try{localStorage.setItem('gam264-theme',key)}catch(e){notify('已切換色系，但瀏覽器無法記住偏好');render();return}render();notify('已套用色系，並記住此瀏覽器的偏好')}}
function settingsPage(){return title('設定','管理成員、服務串接與介面外觀。')+`<div class="ai-settings"><section class="card"><div class="cardhead"><div><h2>成員管理</h2><p>管理成員姓名、帳號與操作權限。</p></div><button type="button" class="settings-chevron" onclick="go('members')" aria-label="開啟管理成員" title="管理成員"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m9 5 7 7-7 7"/></svg></button></div><span class="pill">最高管理權限</span></section><section class="card"><div class="cardhead"><div><h2>AI 服務設定</h2><p>設定 AI 服務連線、資料傳送政策與功能對應。</p></div><button type="button" class="settings-chevron" onclick="go('ai-settings')" aria-label="開啟AI 服務設定" title="AI 服務設定"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m9 5 7 7-7 7"/></svg></button></div><span class="pill">最高管理權限</span></section><section class="card"><div class="cardhead"><div><h2>介面外觀</h2><p>選擇網站色系，設定會保存在目前瀏覽器。</p></div><button type="button" class="settings-chevron" onclick="go('appearance')" aria-label="開啟調整外觀" title="調整外觀"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m9 5 7 7-7 7"/></svg></button></div><p>目前色系：${esc(themes[themeKey].label)}</p></section></div>`}

function appearancePage(){return title('介面外觀','選擇適合工作區的色系。設定會記住在這個瀏覽器。','')+`<div class="rulegrid">${Object.entries(themes).map(([k,t])=>`<section class="card themeoption ${themeKey===k?'chosen':''}"><div class="swatches"><span style="background:${t.primary}"></span><span style="background:${t.accent}"></span><span style="background:${t.bar}"></span><span style="background:${t.bg}"></span></div><h3>${t.label}</h3><p>${k==='janman'?'工作區預設，以深藍與淺藍呈現。':k==='forest'?'保留前一版原型的深綠配色。':'適用其他公司的中性工作介面。'}</p><button style="margin-top:18px" class="${themeKey===k?'primary':''}" aria-pressed="${themeKey===k}" onclick="applyTheme('${k}',true)">${themeKey===k?'✓ 目前使用':'套用色系'}</button></section>`).join('')}</div><section class="card" style="margin-top:22px"><h2>狀態顏色保持一致</h2><div class="actions" style="margin:18px 0">${badge('已匯出')}${badge('待確認')}${badge('處理失敗')}<span class="badge blue">資訊提示</span></div><p>切換品牌色不改變狀態標示、工程圖、遮蔽色與備註色塊。</p><div class="note">此處只設定本機顯示偏好，不會變更其他成員的畫面。</div><button onclick="applyTheme('janman',true)">恢復預設色系</button></section>`}
applyTheme(themeKey);
const nav=[['dashboard','▦','工作總覽'],['cases','▱','案件管理'],['rules','☷','客戶處理規則'],['glossary','','專業翻譯知識庫'],['approval','◇','估價審批'],['sq','▤','SQ 資料整理'],['settings','⚙','設定']];function render(){const oldViewport=document.querySelector('#drawingViewport'),scrollState=oldViewport?{x:oldViewport.scrollLeft,y:oldViewport.scrollTop}:null;document.querySelector('#unsavedBackNotice')?.remove();route=location.hash.slice(1)||'dashboard';if(!['new','edit-case','import','setup'].includes(route)){wizardDraft=null}else if(['import','setup','edit-case'].includes(route)&&!wizardDraft&&current()){wizardDraft=JSON.parse(JSON.stringify(current()))}if(route!=='cases'){caseDeleteMode=false;selectedCaseIds.clear()}if(!current()&&['case','edit-case','import','setup','work','review','export'].includes(route))route='cases';$('#nav').innerHTML='<small>業務工作區</small>'+nav.map(([r,i,t],n)=>(r==='settings'?'<small>系統</small>':'')+`<button class="${r===route||(r==='settings'&&['appearance','members','ai-settings'].includes(route))||(r==='cases'&&['case','new','edit-case','import','setup','work','export','review'].includes(route))?'active':''}" title="${t}" aria-label="${t}" onclick="go('${r}');closeSidebar()"><span class="nav-icon" aria-hidden="true">${navLineIcon(r)}</span><span class="nav-label">${t}${['glossary','approval','sq'].includes(r)?'<span class="nav-tbd" title="後續規劃（TBD）" aria-label="後續規劃">*</span>':''}</span></button>`).join('');$('#crumb').innerHTML=['case','work','review','export','new','edit-case','import','setup'].includes(route)?`<a href="#cases">案件管理</a> <span aria-hidden="true">›</span> ${esc(({case:'編輯案件',work:'圖面工作台',review:'預覽與確認',export:'可匯出項目'})[route]||'建立案件')}`:esc(route==='ai-settings'?'設定 › AI 服務設定':route==='members'?'設定 › 成員管理':route==='appearance'?'設定 › 介面外觀':nav.find(n=>n[0]===route)?.[2]||'工作總覽');let pages={'ai-settings':aiPage,glossary:glossaryPage,dashboard,cases:casesPage,new:newPage,'edit-case':newPage,import:importPage,setup:setupPage,case:casePage,work:workPage,review:reviewPage,export:exportPage,rules:rulesPage,approval:()=>tbdPage('approval'),sq:()=>tbdPage('sq'),settings:settingsPage,members:membersPage,appearance:appearancePage};$('#app').innerHTML=(pages[route]||dashboard)();if(drawingResizeObserver){drawingResizeObserver.disconnect();drawingResizeObserver=null}if(route==='work'){sizeDrawing();bindDrag();if(typeof ResizeObserver!=='undefined'&&document.querySelector('#drawingViewport')){drawingResizeObserver=new ResizeObserver(sizeDrawing);drawingResizeObserver.observe(document.querySelector('#drawingViewport'))}const viewport=document.querySelector('#drawingViewport');if(viewport&&scrollState){viewport.scrollLeft=scrollState.x;viewport.scrollTop=scrollState.y}}};function resetDemo(){if(!confirm('重設本次原型操作與示範資料？'))return;cases=seed();cases.forEach(c=>{if(c.owner==='陳怡安')c.owner=demoUser.name});cid=cases[0].id;fi=0;logs=[];pendingNames=[];filter='全部';query='';writeCaseStore();go('dashboard');render();notify('示範資料已重設')};window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});loadCaseStore();document.querySelector('#accountName').textContent=demoUser.name;render();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort());try{Promise.resolve(document.modelContext.registerTool({name:'get_drawing_case_status',description:'Read current demo case and per-file status without modifying data.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:(input)=>{if(input&&Object.keys(input).length)throw new Error('No arguments accepted');return {caseId:cid,files:current().files.map(f=>({name:f.name,status:f.status}))}}},{signal:lifecycle.signal})).catch(()=>{})}catch(e){console.warn('Optional tool registration unavailable')}}

function syncSidebar(){const mobile=window.matchMedia('(max-width:760px)').matches;const open=mobile?document.body.classList.contains('sidebar-open'):!document.body.classList.contains('sidebar-collapsed');const toggle=document.querySelector('#sidebarToggle');toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'收折選單':'展開選單');document.querySelector('.sidebar-backdrop').hidden=!(mobile&&open);document.querySelector('#sidebar').inert=mobile&&!open;}
function toggleSidebar(){if(window.matchMedia('(max-width:760px)').matches)document.body.classList.toggle('sidebar-open');else document.body.classList.toggle('sidebar-collapsed');syncSidebar();}
function closeSidebar(){document.body.classList.remove('sidebar-open');syncSidebar();}
function openAccountEditor(){document.querySelector('#accountMenu').open=false;openMemberEditor('member-1')}
function saveAccount(event){event.preventDefault();const input=document.querySelector('#accountNameInput'),name=input.value.trim();if(!name){input.setCustomValidity('請輸入姓名');input.reportValidity();return;}input.setCustomValidity('');const old=demoUser.name;demoUser.name=name;cases.forEach(c=>{if(c.owner===old)c.owner=name});document.querySelector('#accountName').textContent=name;document.querySelector('#accountDialog').close();render();notify('示範帳號已更新');}
function openSignOut(){document.querySelector('#accountMenu').open=false;document.querySelector('#signOutDialog').showModal();}
function demoSignOut(){document.querySelector('#signOutDialog').close();document.querySelector('#signedOutDialog').showModal();}
function returnToDemo(){document.querySelector('#signedOutDialog').close();document.querySelector('#accountMenu summary').focus();}
document.querySelector('#accountNameInput').addEventListener('input',e=>e.target.setCustomValidity(''));
document.querySelector('#signedOutDialog').addEventListener('cancel',e=>{e.preventDefault();returnToDemo()});
document.addEventListener('click',e=>{const menu=document.querySelector('#accountMenu');if(!menu.contains(e.target))menu.open=false});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(document.querySelector('dialog[open]'))return;if(route==='work'&&selection){e.preventDefault();clearSelection();return;}document.querySelector('#accountMenu').open=false;closeSidebar();document.querySelector('#sidebarToggle').focus();}});
window.matchMedia('(max-width:760px)').addEventListener('change',()=>{document.body.classList.remove('sidebar-open');syncSidebar()});
if(window.matchMedia('(min-width:761px) and (max-width:1100px)').matches)document.body.classList.add('sidebar-collapsed');
syncSidebar();

function ruleLabel(rule){return rule==='A'?'客戶 A · 右下圖框':rule==='B'?'客戶 B · 左上標誌':'人工確認'}
function caseIconButton(icon,label,action){const paths={edit:'<path d="m16 3 5 5-12 12-6 1 1-6zM14 5l5 5"/>',save:'<path d="M4 3h13l4 4v14H3V3zM7 3v6h10V3M7 21v-8h10v8"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/>'};return `<button class="case-icon ${icon==='trash'?'danger-text':icon==='save'&&unsavedCases.has(current()?.id)?'save-dirty':''}" data-save-action="${icon==='save'}" aria-label="${label}" title="${icon==='save'&&unsavedCases.has(current()?.id)?'有變更尚未儲存，點擊儲存進度':label}" onclick="${action}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[icon]}</svg></button>`}
function caseDialog(id,html){document.getElementById(id)?.remove();const d=document.createElement('dialog');d.id=id;d.className='case-dialog';d.setAttribute('aria-labelledby',id+'Title');d.innerHTML=html;document.body.append(d);d.addEventListener('close',()=>d.remove());d.showModal();return d}
function openRenameCase(){const c=current();const d=caseDialog('renameCaseDialog',`<form onsubmit="renameCase(event)"><h2 id="renameCaseDialogTitle">修改案件名稱</h2><label class="field">案件名稱<input id="renameCaseInput" value="${esc(c.name)}" required maxlength="100"></label><p id="renameError" role="alert"></p><div class="actions"><button type="button" onclick="this.closest('dialog').close()">取消</button><button class="primary">儲存名稱</button></div></form>`);d.dataset.caseId=c.id;d.querySelector('input').select()}
function renameCase(event){event.preventDefault();const d=$('#renameCaseDialog'),name=$('#renameCaseInput').value.trim();if(!name){$('#renameError').textContent='請輸入案件名稱。';return}const next=cases.map(c=>c.id===d.dataset.caseId?{...c,name,savedAt:new Date().toISOString()}:c);if(!writeCaseStore(next,logs)){ $('#renameError').textContent='儲存失敗，請重試。';return}cases=next;d.close();render();notify('案件名稱已更新')}
function openCaseImport(){const c=current();const d=caseDialog('caseImportDialog',`<form onsubmit="submitCaseImport(event)"><h2 id="caseImportDialogTitle">匯入圖面</h2><p>新增圖面至目前案件，既有圖面與編輯內容會保留。</p><label class="field">選擇圖面<input id="caseImportFiles" type="file" multiple accept=".pdf,.png,.jpg,.jpeg" onchange="updateCaseImportNames(Array.from(this.files).map(f=>f.name))"></label><button type="button" onclick="updateCaseImportNames(['BRACKET-B01.pdf','HOUSING-B02.pdf','PLATE-B03.pdf'])">加入三份示範圖面</button><ul id="caseImportNames" class="import-names"></ul><label class="field">本次匯入規則<select id="caseImportRule"><option value="A">客戶 A · 右下圖框 v1.2</option><option value="B">客戶 B · 左上標誌 v1.0</option><option value="manual">不套用規則 · 人工圈選</option></select></label><p class="import-help">原型僅以檔名建立示範圖面，AI 處理為模擬。規則只提供候選位置，仍需逐檔確認。</p><p id="caseImportError" role="alert"></p><div class="actions"><button type="button" onclick="this.closest('dialog').close()">取消</button><button id="caseImportSubmit" class="primary" disabled>匯入並建立處理任務</button></div></form>`);d.dataset.caseId=c.id;d.importNames=[];$('#caseImportRule').value=c.rule||'manual'}
function updateCaseImportNames(names){const d=$('#caseImportDialog');d.importNames=names;$('#caseImportNames').innerHTML=names.map(n=>`<li>${esc(n)}</li>`).join('');$('#caseImportSubmit').disabled=!names.length}
function submitCaseImport(event){event.preventDefault();const d=$('#caseImportDialog'),names=d.importNames||[],rule=$('#caseImportRule').value;if(!names.length)return;const target=cases.find(c=>c.id===d.dataset.caseId);if(!target){$('#caseImportError').textContent='案件不存在，請返回案件管理。';return}const updated={...target,files:[...target.files.map(f=>({...f,rule:f.rule||target.rule||'manual'})),...names.map(name=>({name,rule,status:'待確認',notes:[],accepted:false}))],rule,savedAt:new Date().toISOString()};const next=cases.map(c=>c.id===target.id?updated:c);const nextLogs=[...logs,{caseId:target.id,time:new Date().toLocaleString('zh-TW',{timeZone:'Asia/Taipei'}),file:names.join('、'),action:'匯入 '+names.length+' 份圖面 · '+ruleLabel(rule)}];if(!writeCaseStore(next,nextLogs)){$('#caseImportError').textContent='儲存失敗，請重試。';return}cases=next;logs=nextLogs;d.close();render();notify('圖面已加入案件並儲存')}

function workFileStatus(f){return f.status==='待確認'&&f.accepted?'已確認':f.status}

function parentPage(){return ({'ai-settings':['settings','設定'],case:['cases','案件管理'],work:['case','案件'],review:['work','圖面工作台'],export:['review','預覽與人工確認'],appearance:['settings','設定'],members:['settings','設定'],new:['cases','案件管理'],'edit-case':['cases','案件管理'],import:['edit-case','案件資訊'],setup:['import','匯入圖面']})[route]||['dashboard','工作總覽']}
function pageBackButton(){if(!['case','work','review','export','appearance','members','ai-settings','new','edit-case','import','setup'].includes(route))return '';const [r,label]=parentPage();return `<button type="button" class="page-back" onclick="requestPageBack('${r}')" title="返回${label}" aria-label="返回${label}"><svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="m15 5-7 7 7 7"/></svg></button>`}
function caseExportButton(c){const ready=c.files.some(f=>['可匯出','已匯出'].includes(f.status));const help=ready?'查看已通過最終確認的圖面':c.files.length?'尚無可匯出圖面，請先完成至少一張圖面的最終確認。':'請先匯入圖面並完成確認。';return `<span class="disabled-action-tip" ${ready?'':'tabindex="0"'} title="${help}" aria-label="${help}"><button class="primary" ${ready?'':'disabled'} onclick="go('export')">查看可匯出項目</button><span role="tooltip">${help}</span></span>`}
function savedTimeLabel(c){if(unsavedCases.has(c.id))return '<span class="saved-time unsaved-label" role="status">有變更 · 尚未儲存</span>';if(!c.savedAt)return '<span class="saved-time">尚未儲存</span>';const d=new Date(c.savedAt);return `<span class="saved-time" title="${esc(d.toLocaleString('zh-TW',{timeZone:'Asia/Taipei'}))}">已儲存 ${esc(d.toLocaleTimeString('zh-TW',{timeZone:'Asia/Taipei',hour12:false,hour:'2-digit',minute:'2-digit'}))}</span>`}

function sortedCases(rows){if(route!=='cases'||!caseSortKey)return rows;return [...rows].sort((a,b)=>{let diff=caseSortKey==='files'?a.files.length-b.files.length:String(a[caseSortKey]||'').localeCompare(String(b[caseSortKey]||''),'zh-TW',{numeric:true,sensitivity:'base'});return diff*caseSortDirection})}
function caseSortHeading(key,label){if(route!=='cases')return `<th>${label}</th>`;const active=caseSortKey===key;return `<th aria-sort="${active?(caseSortDirection===1?'ascending':'descending'):'none'}"><button class="sort-heading" onclick="sortCaseTable('${key}')" title="依${label}排序" aria-label="依${label}${active&&caseSortDirection===1?'降冪':'升冪'}排序">${label}<span aria-hidden="true">${active?(caseSortDirection===1?'↑':'↓'):'<svg class="sort-neutral-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M8 19V5m-4 4 4-4 4 4M16 5v14m-4-4 4 4 4-4"/></svg>'}</span></button></th>`}
function sortCaseTable(key){if(!['name','client','owner','files','due'].includes(key))return;caseSortDirection=caseSortKey===key?-caseSortDirection:1;caseSortKey=key;casePageIndex=0;selectedCaseIds.clear();render()}

function navLineIcon(name){const shapes={glossary:'<path d="M12 5c-3-2-6-2-9-1v15c3-1 6-1 9 1 3-2 6-2 9-1V4c-3-1-6-1-9 1zM12 5v15M6 8h3M6 12h3M15 8h3M15 12h3"/>',dashboard:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',cases:'<path d="M3 7V5a2 2 0 0 1 2-2h5l3 3h6a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V7zM3 9h18"/>',rules:'<path d="M14 3H5v18h14V8zM14 3v5h5M8 12l1 1 2-2M13 12h3M8 17l1 1 2-2M13 17h3"/>',approval:'<rect x="5" y="4" width="14" height="17" rx="2"/><rect x="9" y="2" width="6" height="4" rx="1"/><path d="m8 13 3 3 5-6"/>',sq:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M3 9h18M9 9v12M3 15h18"/>',settings:'<path d="m9 3-.7 2.3-2 .9-2.2-.5-2 3.5 1.6 1.8v2l-1.6 1.8 2 3.5 2.2-.5 2 .9L9 21h6l.7-2.3 2-.9 2.2.5 2-3.5-1.6-1.8v-2l1.6-1.8-2-3.5-2.2.5-2-.9L15 3z"/><circle cx="12" cy="12" r="3"/>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" focusable="false" aria-hidden="true">${shapes[name]||shapes.cases}</svg>`}

function loadMembers(){const seed=[{id:'member-1',name:'陳怡安',account:'yian.chen@example.com',title:'業務助理主管',role:'admin'},{id:'member-2',name:'林佳蓉',account:'jiarong.lin@example.com',title:'業務助理',role:'editor'},{id:'member-3',name:'王雅婷',account:'yating.wang@example.com',title:'業務助理',role:'editor'},{id:'member-4',name:'張家豪',account:'jiahao.chang@example.com',title:'業務助理',role:'editor'},{id:'member-5',name:'李承恩',account:'chengen.li@example.com',title:'行政人員',role:'viewer'}];try{const x=JSON.parse(localStorage.getItem('gam264-members'));if(Array.isArray(x)&&x.some(m=>m.id==='member-1')&&x.every(m=>m.id&&m.name&&m.account&&['admin','editor','viewer'].includes(m.role)))return x.map(m=>m.id==='member-1'?{...m,role:'admin',title:'業務助理主管'}:m)}catch{}return seed}
function roleName(role){return ({admin:'最高管理權限',editor:'編輯權限',viewer:'檢視權限'})[role]||'檢視權限'}
function membersPage(){return title('成員管理','管理成員帳號與權限。',btn('＋ 新增成員',"openMemberEditor()",'primary'))+`<div class="note">目前登入：${esc(demoUser.name)} · 業務助理主管 · 最高管理權限。以下姓名及帳號均為虛構示範資料，權限尚未串接正式登入與後端授權。</div><section class="card"><div class="cardhead"><h2>工作區成員</h2><span class="pill">${members.length} 位</span></div><div class="tablewrap"><table><thead><tr><th>姓名</th><th>帳號</th><th>職稱</th><th>權限</th><th>操作</th></tr></thead><tbody>${members.map(m=>`<tr><td><b>${esc(m.name)}</b>${m.id==='member-1'?'<small>目前登入</small>':''}</td><td>${esc(m.account)}</td><td>${esc(m.title)}</td><td><span class="badge ${m.role==='admin'?'green':'blue'}">${roleName(m.role)}</span></td><td><div class="member-actions"><button onclick="openMemberEditor('${m.id}')">編輯</button><button onclick="openMemberEditor('${m.id}',true)" ${m.id==='member-1'?'disabled title="目前登入主管的最高權限不可調降"':''}>更改權限</button><button class="case-icon danger-text" onclick="deleteMemberDialog('${m.id}')" ${m.id==='member-1'?'disabled title="不可刪除目前登入帳號"':'title="刪除成員"'} aria-label="刪除${esc(m.name)}">${caseActionIcon('delete')}</button></div></td></tr>`).join('')}</tbody></table></div></section><section class="card" style="margin-top:20px"><h2>權限說明</h2><p><b>最高管理權限：</b>管理所有案件、規則、設定及成員。</p><p><b>編輯權限：</b>建立及編輯案件、處理圖面；不可管理成員。</p><p><b>檢視權限：</b>查看案件及圖面；不可修改內容與成員。</p></section>`}
function openMemberEditor(id,permissionOnly=false){const m=members.find(x=>x.id===id);caseDialog('memberDialog',`<form onsubmit="saveMember(event)"><h2 id="memberDialogTitle">${permissionOnly?'更改權限':m?'編輯成員':'新增成員'}</h2><input type="hidden" name="id" value="${m?.id||''}"><label class="field">姓名<input name="name" value="${esc(m?.name||'')}" required maxlength="40" ${permissionOnly?'readonly':''}></label><label class="field">帳號（電子郵件）<input name="account" type="email" value="${esc(m?.account||'')}" required maxlength="100" ${permissionOnly?'readonly':''}></label><label class="field">職稱<input name="title" value="${esc(m?.title||'業務助理')}" required maxlength="40" ${id==='member-1'?'disabled':permissionOnly?'readonly':''}></label><label class="field">權限<select name="role" ${id==='member-1'?'disabled':''}>${['admin','editor','viewer'].map(r=>`<option value="${r}" ${(m?.role||'editor')===r?'selected':''}>${roleName(r)}</option>`).join('')}</select></label><p id="memberError" role="alert"></p><div class="actions"><button type="button" onclick="this.closest('dialog').close()">取消</button><button class="primary">儲存</button></div></form>`)}
function saveMember(event){event.preventDefault();const data=new FormData(event.target),id=data.get('id'),old=members.find(m=>m.id===id),name=data.get('name').trim(),account=data.get('account').trim().toLowerCase(),job=(data.get('title')||old?.title||'').trim(),role=id==='member-1'?'admin':data.get('role');if(!name||!job||!['admin','editor','viewer'].includes(role)){$('#memberError').textContent='請填寫完整資料。';return}if(members.some(m=>m.id!==id&&m.account.toLowerCase()===account)){$('#memberError').textContent='此帳號已存在，請使用其他帳號。';return}const m={id:id||'member-'+Date.now(),name,account,title:id==='member-1'?'業務助理主管':job,role};const next=old?members.map(x=>x.id===id?m:x):[...members,m];try{localStorage.setItem('gam264-members',JSON.stringify(next))}catch{$('#memberError').textContent='儲存失敗，請重試。';return}members=next;if(id==='member-1'){demoUser={...m};$('#accountName').textContent=m.name}$('#memberDialog').close();render();notify('成員資料已儲存；既有案件的建立者紀錄保留原姓名。')}
function deleteMemberDialog(id){const m=members.find(x=>x.id===id);if(!m||id==='member-1')return;caseDialog('memberDeleteDialog',`<h2 id="memberDeleteDialogTitle">刪除成員？</h2><p>確定刪除 ${esc(m.name)}（${esc(m.account)}）？既有案件及建立者紀錄會保留。</p><p id="memberDeleteError" role="alert"></p><div class="actions"><button onclick="this.closest('dialog').close()">取消</button><button class="danger-text" onclick="confirmMemberDelete('${id}')">確認刪除</button></div>`)}
function confirmMemberDelete(id){if(id==='member-1')return;const next=members.filter(m=>m.id!==id);try{localStorage.setItem('gam264-members',JSON.stringify(next))}catch{$('#memberDeleteError').textContent='刪除未儲存，請重試。';return}members=next;$('#memberDeleteDialog').close();render();notify('成員已刪除')}

function markCaseUnsaved(){if(!current()||wizardDraft)return;unsavedCases.add(current().id);document.querySelectorAll('[data-save-action="true"]').forEach(b=>{b.classList.add('save-dirty');b.title='有變更尚未儲存，點擊儲存進度';b.setAttribute('aria-label','儲存進度，有未儲存變更')});document.querySelectorAll('.saved-time').forEach(el=>{el.textContent='有變更 · 尚未儲存';el.classList.add('unsaved-label');el.setAttribute('role','status')})}
function requestPageBack(target){if(!['work','review','export','case'].includes(route)||!unsavedCases.has(current()?.id)){go(target);return}document.querySelector('#unsavedBackNotice')?.remove();const notice=document.createElement('section');notice.id='unsavedBackNotice';notice.className='unsaved-back-notice';notice.setAttribute('role','region');notice.setAttribute('aria-label','尚未儲存的工作進度');notice.innerHTML=`<strong>工作進度尚未儲存</strong><p>可先儲存再返回，或直接返回。直接返回會保留本次開啟期間的編輯，重新整理或關閉頁面可能遺失。</p><div class="actions"><button onclick="dismissBackNotice()">繼續編輯</button><button onclick="dismissBackNotice();go('${target}')">直接返回</button><button class="primary" onclick="saveBeforeBack('${target}')">先儲存再返回</button></div>`;document.body.append(notice);notice.querySelector('button').focus()}
function dismissBackNotice(){document.querySelector('#unsavedBackNotice')?.remove()}
function saveBeforeBack(target){if(saveCaseProgress()){dismissBackNotice();go(target)}}
document.addEventListener('input',e=>{if(route==='work'&&e.target.closest('#noteText'))dirty()});

function drawingConfirmation(f){return `<section class="drawing-confirm-bar ${f.accepted?'is-confirmed':'is-pending'}" aria-label="圖面確認狀態"><div class="drawing-confirm-info"><div class="drawing-status-line"><span class="drawing-status-label">本張圖面狀態</span><span class="drawing-state ${f.accepted?'confirmed':'pending'}" role="status">${f.accepted?'已確認':'待確認'}</span></div><p>${f.accepted?'可繼續核對其他圖面，或前往「預覽與確認」。再次修改內容後需重新確認。':'請核對遮蔽範圍、備註色塊與必要技術資訊，完成後再標記確認。'}</p></div>${f.accepted?'<span class="drawing-complete-hint"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="m7 12 3 3 7-7"/></svg>本張核對完成</span>':'<button class="confirm-drawing" onclick="acceptMask()"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="m5 12 4 4L19 6"/></svg>標記為已確認</button>'}</section>`}

function isExportReady(f){return ['可匯出','已匯出'].includes(f.status)}
function exportReadyFiles(c){return c.files.filter(isExportReady)}
function exportSummary(c){const ready=exportReadyFiles(c).length;return `<div class="review-count-summary">案件總計 <b>${c.files.length} 份</b><span>可匯出（含已匯出） <b>${ready} 份</b></span><span>尚待處理 <b>${c.files.length-ready} 份</b></span></div>`}
function reviewExportAction(){const n=exportReadyFiles(current()).length;return `<button class="primary" ${n?'':'disabled'} onclick="go('export')">查看可匯出項目（${n}）</button>`}
let reviewQuery='',reviewFilter='全部',reviewListPage=0,reviewZoom=100,reviewCaseId=null;
function reviewStatus(f){return isExportReady(f)?f.status:f.status==='處理失敗'?'處理失敗':f.accepted?'待最終核對':'待工作台確認'}
function reviewMatches(){return current().files.map((f,i)=>({f,i})).filter(({f})=>(reviewFilter==='全部'||reviewStatus(f)===reviewFilter)&&f.name.toLocaleLowerCase().includes(reviewQuery.trim().toLocaleLowerCase()))}
function reviewList(){const rows=reviewMatches(),pages=Math.max(1,Math.ceil(rows.length/20));reviewListPage=Math.max(0,Math.min(reviewListPage,pages-1));return `<p class="review-list-count" role="status">符合 ${rows.length} / 共 ${current().files.length} 張</p><div class="review-file-items">${rows.slice(reviewListPage*20,reviewListPage*20+20).map(({f,i})=>`<button class="review-file ${i===fi?'active':''}" aria-current="${i===fi?'true':'false'}" onclick="selectReviewFile(${i})"><strong>${esc(f.name)}</strong><span class="review-file-state ${isExportReady(f)?'done':f.status==='處理失敗'?'failed':''}">${reviewStatus(f)}</span></button>`).join('')||'<p>沒有符合條件的圖面</p>'}</div><div class="review-pagination"><button aria-label="上一頁圖面清單" ${reviewListPage?'':'disabled'} onclick="reviewListPage--;refreshReviewList()">上一頁</button><span>${reviewListPage+1} / ${pages}</span><button aria-label="下一頁圖面清單" ${reviewListPage+1<pages?'':'disabled'} onclick="reviewListPage++;refreshReviewList()">下一頁</button></div>`}
function refreshReviewList(){document.querySelector('#reviewFileResults').innerHTML=reviewList();const rows=reviewMatches(),pos=rows.findIndex(r=>r.i===fi);document.querySelector('#reviewPrevious').disabled=pos<=0;document.querySelector('#reviewNext').disabled=pos<0||pos>=rows.length-1}
function selectReviewFile(i){fi=i;reviewZoom=100;render()}
function reviewAdjacent(step){const rows=reviewMatches(),pos=rows.findIndex(r=>r.i===fi),next=rows[pos+step];if(next){reviewListPage=Math.floor((pos+step)/20);selectReviewFile(next.i)}}
function setReviewZoom(value){reviewZoom=Math.max(50,Math.min(200,value));document.querySelector('#reviewPaper').style.width=reviewZoom+'%';document.querySelector('#reviewZoomValue').textContent=reviewZoom+'%';document.querySelector('#reviewZoomOut').disabled=reviewZoom===50;document.querySelector('#reviewZoomIn').disabled=reviewZoom===200}
function reviewPreview(f){if(f.status==='處理失敗')return '<div class="review-preview-error"><h3>此圖面處理失敗，尚無可核對的成果</h3><p>請先重試處理，再進行最終核對。</p>'+btn('查看原因與重試',`openFailureDialog(${fi})`)+'</div>';return `<div class="review-preview-viewport"><div id="reviewPaper" class="review-paper" style="width:${reviewZoom}%">${drawing()}${(f.masks||[]).map(o=>`<div class="review-overlay" style="left:${o.x}%;top:${o.y}%;width:${o.w}%;height:${o.h}%;background:${o.color}"></div>`).join('')}${f.notes.map(o=>`<div class="review-overlay review-note formatted-note" style="left:${o.x}%;top:${o.y}%;width:${o.w}%;min-height:${o.h}%;background:${o.color};color:${textColor(o.color)}">${noteMarkup(o)}</div>`).join('')}</div></div><div class="review-preview-tools"><span>最終圖面預覽 · 唯讀</span><div><button id="reviewZoomOut" aria-label="縮小預覽" onclick="setReviewZoom(reviewZoom-25)">−</button><output id="reviewZoomValue">${reviewZoom}%</output><button id="reviewZoomIn" aria-label="放大預覽" onclick="setReviewZoom(reviewZoom+25)">＋</button><button onclick="setReviewZoom(100)">適合寬度</button></div></div>`}
function reviewProgress(){const c=current(),f=file();if(reviewCaseId!==c.id){reviewCaseId=c.id;reviewQuery='';reviewFilter='全部';reviewListPage=Math.floor(fi/20);reviewZoom=100}const rows=reviewMatches(),pos=rows.findIndex(r=>r.i===fi);return `<p class="review-important review-guidance">每張圖面須各自完成三項核對，通過後才會列入匯出項目。</p><section class="review-layout"><div class="card review-browser"><h2>核對圖面</h2><label class="field">搜尋檔名<input type="search" placeholder="輸入檔名搜尋" value="${esc(reviewQuery)}" oninput="reviewQuery=this.value;reviewListPage=0;refreshReviewList()"></label><label class="field">核對狀態<select onchange="reviewFilter=this.value;reviewListPage=0;refreshReviewList()">${['全部','待工作台確認','待最終核對','處理失敗','可匯出','已匯出'].map(t=>`<option ${t===reviewFilter?'selected':''}>${t}</option>`).join('')}</select></label><div id="reviewFileResults">${reviewList()}</div></div><div class="card review-preview"><div class="cardhead"><div><h2>最終出圖預覽</h2><p class="review-current-name">${esc(f.name)}</p></div><span>第 ${fi+1} / ${c.files.length} 張</span></div>${reviewPreview(f)}<div class="review-navigation"><button id="reviewPrevious" onclick="reviewAdjacent(-1)" ${pos>0?'':'disabled'}>上一張</button>${btn('繼續編輯此圖面',"go('work')")}<button id="reviewNext" onclick="reviewAdjacent(1)" ${pos>=0&&pos<rows.length-1?'':'disabled'}>下一張</button></div></div></section>`}

function syncReviewApproval(){const checked=[1,2,3].every(i=>document.querySelector('#check'+i)?.checked),f=file(),button=document.querySelector('#reviewApprove');button.disabled=!checked||!f.accepted||f.status==='處理失敗'||isExportReady(f);document.querySelector('#reviewApprovalHint').textContent=isExportReady(f)?'本張已通過最終確認':!f.accepted?'請先在工作台確認本張圖面':checked?'三項核對已完成，可確認通過':'請完成上方三項核對'}
function syncExportSelection(){document.querySelector('#exportSelected').disabled=(typeof pdfBusy!=='undefined'&&pdfBusy)||!document.querySelector('.exportcheck:checked')}

function updateCaseDueDate(input){const c=current();if(!c)return;if(!input.value||!input.validity.valid){input.value=c.due;notify('請選擇有效的預定交付日。');return;}if(input.value===c.due)return;c.due=input.value;markCaseUnsaved();notify('交付日已修改，請儲存進度。');}

function openPrototypeInfo(){caseDialog('prototypeInfo',`<h2 id="prototypeInfoTitle">互動原型 v0.4</h2><p>使用虛構圖面與示範資料，支援匯入本機 PDF。</p><p>進度儲存於此瀏覽器 · 使用同一瀏覽器可繼續編輯</p><p>匯入檔案保存在此瀏覽器，AI 服務尚未串接。</p><p>選單中的 * 代表後續規劃（TBD）項目。</p><div class="actions"><button type="button" onclick="resetDemo()">重設示範資料</button><button type="button" class="primary" onclick="this.closest('dialog').close()">關閉</button></div>`);}

function visibleCaseRows(){
 const rows=sortedCases(matchingCases(filter));
 if(route!=='cases')return rows.slice(0,10);
 casePageIndex=Math.max(0,Math.min(casePageIndex,Math.max(0,Math.ceil(rows.length/CASE_PAGE_SIZE)-1)));
 return rows.slice(casePageIndex*CASE_PAGE_SIZE,(casePageIndex+1)*CASE_PAGE_SIZE);
}
function goCasePage(page){
 const count=Math.max(1,Math.ceil(matchingCases(filter).length/CASE_PAGE_SIZE));
 const value=Number(page);if(!Number.isInteger(value))return;
 casePageIndex=Math.max(0,Math.min(value-1,count-1));selectedCaseIds.clear();render();
 document.querySelector('#casePagination')?.scrollIntoView({block:'nearest'});
}
function casePaginationContent(){
 visibleCaseRows();
 const total=matchingCases(filter).length,pages=Math.max(1,Math.ceil(total/CASE_PAGE_SIZE)),page=casePageIndex+1;
 return `<span class="case-page-summary" role="status">${total?casePageIndex*CASE_PAGE_SIZE+1:0}–${Math.min(page*CASE_PAGE_SIZE,total)} 件 / 共 ${total} 件</span>
 <div class="case-page-controls"><button aria-label="上一頁案件" ${page===1?'disabled':''} onclick="goCasePage(${page-1})">上一頁</button><span>第 ${page} / ${pages} 頁</span><button aria-label="下一頁案件" ${page===pages?'disabled':''} onclick="goCasePage(${page+1})">下一頁</button></div>
 <form class="case-page-jump" onsubmit="event.preventDefault();goCasePage(this.elements.page.value)"><label for="caseJumpPage">跳至</label><input id="caseJumpPage" name="page" type="number" inputmode="numeric" min="1" max="${pages}" value="${page}" required aria-label="跳至案件頁碼" ${pages===1?'disabled':''}><span>頁</span><button type="submit" ${pages===1?'disabled':''}>前往</button></form>`;
}
